INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('545255c1-8451-51e7-ac4d-cce4693e4b52', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 7, 7, 'A polythene rod is rubbed with a woollen cloth and becomes negatively charged. What has happened?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons have moved from the cloth to the rod', NULL, false, NULL, false, NULL, 'Friction transfers electrons; protons are fixed in the nuclei and charge is never created. Mark scheme (1 mark). B1: C (Electrons have moved from the cloth to the rod).', 1, NULL, NULL),
('309b029c-afac-5efc-88a0-25ea59aa44eb', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 8, 8, 'When an insulator is charged by friction, which particles are transferred?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons', NULL, false, NULL, false, NULL, 'Only the outer electrons are loosely held enough to be rubbed off. Mark scheme (1 mark). B1: A (Electrons).', 1, NULL, NULL),
('7b0eb1dc-439e-52d6-887a-eda3ab6534ef', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 9, 9, 'A plastic comb gains a charge of −4.8 × 10⁻⁸ C when it is pulled through dry hair. How many electrons has it gained? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3e11', NULL, false, NULL, false, NULL, 'N = Q/e = 4.8 × 10⁻⁸ ÷ 1.60 × 10⁻¹⁹ = 3.00 × 10¹¹. Mark scheme (2 marks). C1: N = Q/e. A1: N = 3.00 × 10¹¹.', 2, NULL, NULL),
('a3dca644-d57c-5976-ad7d-faea29596801', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 10, 10, 'A balloon rubbed on a jumper gains a charge of +3.2 nC. How many electrons have been removed from it? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '2e10', NULL, false, NULL, false, NULL, 'N = Q/e = 3.2 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = 2.00 × 10¹⁰. Mark scheme (2 marks). C1: nC → C and N = Q/e. A1: N = 2.0 × 10¹⁰.', 2, NULL, NULL),
('92f479dd-ce80-52c7-b5e8-ec151b87667d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 11, 11, 'A negatively charged balloon sticks to an uncharged wall. Why?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons in the wall are repelled, leaving the nearby surface slightly positive, which attracts the balloon', NULL, false, NULL, false, NULL, 'The balloon induces a separation of charge; the opposite charge is closer, so attraction wins. Mark scheme (1 mark). B1: D (Electrons in the wall are repelled, leaving the nearby surface slightly positive, which attracts the balloon).', 1, NULL, NULL),
('c3479831-9064-5063-821a-dddfcd9a790c', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 12, 12, 'Which unit is equivalent to the coulomb?', NULL, 1, 'multiple_choice'::answer_type, 'A s', NULL, false, NULL, false, NULL, 'Q = It, so 1 C = 1 A × 1 s. Mark scheme (1 mark). B1: B (A s).', 1, NULL, NULL),
('c6dd2de7-0a9f-5d7d-b5f8-b4ddf0e283c4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 13, 13, 'Which of these values could NOT be the charge on an object?', NULL, 1, 'multiple_choice'::answer_type, '2.4 × 10⁻¹⁹ C', NULL, false, NULL, false, NULL, 'Charge is quantised in multiples of e = 1.6 × 10⁻¹⁹ C; 2.4 × 10⁻¹⁹ C is 1.5e. Mark scheme (1 mark). B1: C (2.4 × 10⁻¹⁹ C).', 1, NULL, NULL),
('bf2c31eb-0dec-5a83-9119-a725d848b911', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 14, 14, 'Two identical metal spheres carry charges of +6.0 nC and −2.0 nC. They are touched together and then separated. Calculate the charge on each sphere.', NULL, 1, 'numeric'::answer_type, '2 nC', 'nC', false, NULL, false, NULL, 'Total charge = 6.0 + (−2.0) = 4.0 nC, shared equally: each = 4.0 ÷ 2 = 2.0 nC. Mark scheme (2 marks). C1: charge conserved and shared equally. A1: Q = 2.0 nC.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 230" role="img" aria-labelledby="fg187f27de-t fg187f27de-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg187f27de-t">Two charged spheres</title><desc id="fg187f27de-d">Two identical metal spheres on insulating stands carrying +6.0 nC and −2.0 nC, before they are touched together.</desc><circle cx="159" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="148" x2="159" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="137" y1="190" x2="181" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="159" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+6.0 nC</text><circle cx="261" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="261" y1="148" x2="261" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="239" y1="190" x2="283" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="261" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">−2.0 nC</text></svg>', 'Two identical metal spheres on insulating stands carrying +6.0 nC and −2.0 nC, before they are touched together.'),
('6d69699e-2774-50da-8fbf-d2ff99dd29ba', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 15, 15, 'Why is a metal a good electrical conductor?', NULL, 1, 'multiple_choice'::answer_type, 'It contains many free electrons that can move through it', NULL, false, NULL, false, NULL, 'The delocalised electrons in a metal move easily when a force acts on them. Mark scheme (1 mark). B1: A (It contains many free electrons that can move through it).', 1, NULL, NULL),
('d7c9e9d8-7560-5a2b-a58f-4bef74740be4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 16, 16, 'A positively charged metal sphere on an insulating stand is connected to earth by a wire. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons flow from the earth to the sphere until it is neutral', NULL, false, NULL, false, NULL, 'The sphere lacks electrons; electrons flow up from earth to neutralise it. Mark scheme (1 mark). B1: D (Electrons flow from the earth to the sphere until it is neutral).', 1, NULL, NULL),
('9892386e-1966-5dad-b868-bca91c0561e5', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 17, 17, 'A spark transfers 5.0 µC of charge in 2.0 µs. Calculate the average current in the spark.', NULL, 1, 'numeric'::answer_type, '2.5', 'A', false, NULL, false, NULL, 'I = Q/t = 5.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁶ = 2.5 A. Mark scheme (2 marks). C1: I = Q/t. A1: I = 2.5 A.', 2, NULL, NULL),
('eede944f-be07-5b3a-99f3-6c40a513c88d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 18, 18, 'What does the principle of conservation of charge state?', NULL, 1, 'multiple_choice'::answer_type, 'The total charge of an isolated system stays constant', NULL, false, NULL, false, NULL, 'Rubbing only moves charge: the gain on one object equals the loss on the other. Mark scheme (1 mark). B1: B (The total charge of an isolated system stays constant).', 1, NULL, NULL),
('4f87377a-eee5-5a9a-9143-6e7136537dc1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 19, 19, 'How many electrons together have a total charge of −1.0 C? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.25e18', NULL, false, NULL, false, NULL, 'N = 1.0 ÷ 1.60 × 10⁻¹⁹ = 6.25 × 10¹⁸. Mark scheme (1 mark). A1: N = 6.25 × 10¹⁸.', 1, NULL, NULL),
('8b69c661-01d5-5205-83a0-7e4d27b10365', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 20, 20, 'A charged comb picks up small pieces of uncharged paper. Why are the pieces attracted?', NULL, 1, 'multiple_choice'::answer_type, 'Charge is induced in the paper, with opposite charge nearer the comb', NULL, false, NULL, false, NULL, 'The nearer induced charge is attracted more strongly than the further like charge is repelled. Mark scheme (1 mark). B1: C (Charge is induced in the paper, with opposite charge nearer the comb).', 1, NULL, NULL),
('1f54c488-9379-5cbf-ad01-d5fbfe90d55b', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 21, 21, 'A negatively charged rod is brought near a suspended light ball and the ball is repelled. What can be concluded?', NULL, 1, 'multiple_choice'::answer_type, 'The ball is negatively charged', NULL, false, NULL, false, NULL, 'Attraction could mean an uncharged ball, but only like charges repel, so repulsion is a reliable test. Mark scheme (1 mark). B1: A (The ball is negatively charged).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 270" role="img" aria-labelledby="fgc3507c09-t fgc3507c09-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc3507c09-t">Ball repelled by a rod</title><desc id="fgc3507c09-d">A light ball hanging on a thread is pushed away from a negatively charged rod brought near it, so the thread is deflected; F is the electric force on the ball.</desc><line x1="70" y1="30" x2="170" y2="30" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="30" x2="67" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="30" x2="85" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111" y1="30" x2="103" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129" y1="30" x2="121" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="30" x2="139" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165" y1="30" x2="157" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="30" x2="120" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 4"/><line x1="120" y1="30" x2="166.4" y2="172.7" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="166.4" cy="172.7" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="162.6" y1="161.2" x2="146.1" y2="110.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="144.1,104.2 150.2,110.8 143,113.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="166.7" y="130.4" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">T</text><line x1="166.4" y1="184.7" x2="166.4" y2="236.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="166.4,242.7 162.5,234.5 170.2,234.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="176.4" y="238.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">W</text><line x1="178.4" y1="172.7" x2="230.1" y2="172.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="236.4,172.7 228.2,176.5 228.2,168.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="242.4" y="172.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">F</text></svg>', 'A light ball hanging on a thread is pushed away from a negatively charged rod brought near it, so the thread is deflected; F is the electric force on the ball.'),
('e388adaf-e4c8-5fb0-bf7e-68945b8fca23', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 22, 22, 'A lightning flash transfers 20 C of charge to the ground in 0.50 ms. Calculate the average current.', NULL, 1, 'numeric'::answer_type, '40000', 'A', false, NULL, false, NULL, 'I = Q/t = 20 ÷ 0.50 × 10⁻³ = 4.0 × 10⁴ A. Mark scheme (2 marks). C1: I = Q/t with t in s. A1: I = 4.0 × 10⁴ A.', 2, NULL, NULL),
('3efefaa6-cf0b-5ba0-83dc-448f4cc93753', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 23, 23, 'The belt of a Van de Graaff generator carries charge to the dome at a steady rate of 3.0 µA. The dome starts uncharged. Calculate the time taken for the charge on the dome to reach 15 µC.', NULL, 2, 'numeric'::answer_type, '5', 's', false, NULL, false, NULL, 't = Q/I = 15 × 10⁻⁶ ÷ 3.0 × 10⁻⁶ = 5.0 s. Mark scheme (3 marks). C1: current = rate of flow of charge. C1: t = Q/I. A1: t = 5.0 s.', 3, NULL, NULL),
('c30c48d4-63f0-5073-afe5-6c57758113bc', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 24, 24, 'A neutral metal sphere is charged by induction using a positively charged rod: the rod is held near the sphere, the sphere is earthed, the earth connection is removed and then the rod is removed. What is the final charge on the sphere?', NULL, 2, 'multiple_choice'::answer_type, 'Negative', NULL, false, NULL, false, NULL, 'With the rod near, electrons flow up from earth; breaking the earth before removing the rod traps them, leaving a net negative charge. Mark scheme (3 marks). C1: electrons flow from earth. C1: trapped when earth removed first. A1: D (Negative).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fg8d77c17d-t fg8d77c17d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8d77c17d-t">Charging by induction</title><desc id="fg8d77c17d-d">A neutral metal sphere on an insulating stand with a positively charged rod held near it; the sphere is connected to earth.</desc><circle cx="180" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="148" x2="180" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="158" y1="190" x2="202" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="80" y="50" width="16" height="120" rx="4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="66" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="94" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="150" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><line x1="199.6" y1="139.6" x2="230" y2="180" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="180" x2="244" y2="180" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221" y1="185" x2="239" y2="185" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="190" x2="234" y2="190" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A neutral metal sphere on an insulating stand with a positively charged rod held near it; the sphere is connected to earth.'),
('ef2ea9eb-837f-5c56-a0c1-926235776241', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 25, 25, 'Three identical metal spheres A, B and C are on insulating stands. A carries +9.0 nC and B and C are uncharged. A is touched to B and separated, then A is touched to C and separated. Calculate the final charge on A.', NULL, 2, 'numeric'::answer_type, '2.25 nC', 'nC', false, NULL, false, NULL, 'After touching B: A = 9.0 ÷ 2 = 4.5 nC. After touching C: A = 4.5 ÷ 2 = 2.25 nC. Mark scheme (3 marks). C1: charge shared equally each time. C1: two halvings. A1: Q_A = 2.25 nC.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 230" role="img" aria-labelledby="fgf29b2a41-t fgf29b2a41-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf29b2a41-t">Sharing charge</title><desc id="fgf29b2a41-d">Three identical metal spheres A, B and C on insulating stands: A carries +9.0 nC and B and C are uncharged.</desc><circle cx="108" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="108" y1="148" x2="108" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="86" y1="190" x2="130" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><text x="108" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+9.0 nC</text><circle cx="210" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="210" y1="148" x2="210" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="188" y1="190" x2="232" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="210" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text><text x="210" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">uncharged</text><circle cx="312" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="312" y1="148" x2="312" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="290" y1="190" x2="334" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="312" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">C</text><text x="312" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">uncharged</text></svg>', 'Three identical metal spheres A, B and C on insulating stands: A carries +9.0 nC and B and C are uncharged.'),
('1782fcc1-e386-5905-8f83-d1635250098d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 26, 26, 'A gold-leaf electroscope is negatively charged so its leaf is raised. A negatively charged rod is brought near its cap without touching. What happens to the leaf?', NULL, 2, 'multiple_choice'::answer_type, 'It rises further', NULL, false, NULL, false, NULL, 'The rod repels more electrons down into the stem and leaf, increasing the repulsion. Mark scheme (3 marks). C1: electrons pushed down to leaf. C1: more like charge, more repulsion. A1: B (It rises further).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 280" role="img" aria-labelledby="fgc5cab470-t fgc5cab470-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc5cab470-t">Charged electroscope</title><desc id="fgc5cab470-d">A gold-leaf electroscope, negatively charged so that its leaf is raised, with a negatively charged rod brought near its cap without touching.</desc><rect x="120" y="20" width="60" height="10" rx="3" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="30" x2="150" y2="170" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="90" width="160" height="150" rx="10" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="160" x2="148" y2="200" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152" y1="160" x2="177.2" y2="196" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="190" y="205" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">gold leaf</text><text x="110" y="25" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">cap</text><rect x="194" y="4" width="96" height="14" rx="4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="208" y="11" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="231" y="11" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="254" y="11" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="277" y="11" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text></svg>', 'A gold-leaf electroscope, negatively charged so that its leaf is raised, with a negatively charged rod brought near its cap without touching.'),
('f7a4275f-853b-5868-9b8d-7e4b7c665849', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 27, 27, 'Calculate the total charge of all the electrons in 1.0 g of hydrogen atoms (molar mass 1.0 g mol⁻¹, one electron per atom). Take N_A = 6.02 × 10²³ mol⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '96320', 'C', false, NULL, false, NULL, '1.0 g is 1.0 mol, so N = 6.02 × 10²³ electrons. Q = 6.02 × 10²³ × 1.60 × 10⁻¹⁹ = 9.63 × 10⁴ C. Mark scheme (3 marks). C1: one mole of electrons. C1: Q = Ne. A1: Q = 9.63 × 10⁴ C.', 3, NULL, NULL),
('c3179a34-6edc-5c23-835f-675742b7140b', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 28, 28, 'In a photocopier, a toner particle carries a charge of −2.4 × 10⁻¹⁵ C. How many excess electrons does it carry? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '15000', NULL, false, NULL, false, NULL, 'N = Q/e = 2.4 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁹ = 1.50 × 10⁴. Mark scheme (3 marks). C1: N = Q/e. C1: substitution. A1: N = 1.5 × 10⁴.', 3, NULL, NULL),
('ec3cae4e-bf28-5ed6-aac7-51dbcd62526a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 29, 29, 'A charged plastic rod is touched at one end by a finger, but the rest of the rod stays charged. A charged metal rod on an insulating stand loses all its charge when touched. Why the difference?', NULL, 2, 'multiple_choice'::answer_type, 'Charge cannot move through the plastic, so only the touched spot is discharged; in the metal, charge flows freely to the finger', NULL, false, NULL, false, NULL, 'In an insulator electrons are bound to atoms; in a conductor free electrons let the whole object discharge. Mark scheme (3 marks). C1: insulator: charges cannot move. C1: conductor: charges flow away. A1: C (Charge cannot move through the plastic, so only the touched spot is discharged; in the metal, charge flows freely to the finger).', 3, NULL, NULL),
('e270ef0f-ca79-544b-9c3a-9dca77e825f5', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 30, 30, 'An electrostatic paint sprayer gives each paint droplet a charge of −1.6 × 10⁻¹⁴ C. The sprayer delivers a current of 50 µA. Calculate the number of droplets sprayed per second.', NULL, 2, 'numeric'::answer_type, '3.125e9', 's⁻¹', false, NULL, false, NULL, 'Droplets per second = I ÷ q = 50 × 10⁻⁶ ÷ 1.6 × 10⁻¹⁴ = 3.12 × 10⁹ s⁻¹. Mark scheme (3 marks). C1: I = charge per second. C1: ÷ charge per droplet. A1: rate = 3.12 × 10⁹ s⁻¹.', 3, NULL, NULL),
('abdaeccf-b37a-54fa-b4d3-4d1065704cb5', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 31, 31, 'An uncharged metal sphere hanging on a thread is attracted towards a positively charged rod. Which explanation is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Free electrons move to the near side; attraction of this nearer negative charge exceeds repulsion of the further positive charge', NULL, false, NULL, false, NULL, 'Net charge stays zero, but the separated charges are at different distances, and force decreases with distance. Mark scheme (3 marks). C1: electrons move to near side. C1: nearer charge gives the larger force. A1: A (Free electrons move to the near side; attraction of this nearer negative charge exceeds repulsion of the further positive charge).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 270" role="img" aria-labelledby="fg3c68fbbe-t fg3c68fbbe-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3c68fbbe-t">Sphere attracted to a rod</title><desc id="fg3c68fbbe-d">An uncharged metal sphere hanging on a thread is pulled towards a positively charged rod, so the thread is deflected towards the rod; F is the attractive force.</desc><line x1="70" y1="30" x2="170" y2="30" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="30" x2="67" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="30" x2="85" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111" y1="30" x2="103" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129" y1="30" x2="121" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="30" x2="139" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165" y1="30" x2="157" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="30" x2="120" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 4"/><line x1="120" y1="30" x2="166.4" y2="172.7" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="166.4" cy="172.7" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="162.6" y1="161.2" x2="146.1" y2="110.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="144.1,104.2 150.2,110.8 143,113.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="166.7" y="130.4" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">T</text><line x1="166.4" y1="184.7" x2="166.4" y2="236.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="166.4,242.7 162.5,234.5 170.2,234.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="176.4" y="238.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">W</text><line x1="178.4" y1="172.7" x2="230.1" y2="172.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="236.4,172.7 228.2,176.5 228.2,168.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="242.4" y="172.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">F</text></svg>', 'An uncharged metal sphere hanging on a thread is pulled towards a positively charged rod, so the thread is deflected towards the rod; F is the attractive force.'),
('88b5429c-0060-5b34-8103-cc775b8002c2', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 32, 32, 'A person walking across a nylon carpet becomes charged to −0.50 µC. When they touch a metal door handle, they discharge completely in 1.0 µs. (a) Calculate the number of electrons that flow. (b) Calculate the average current. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.5', 'A', false, NULL, false, NULL, '(a) N = 0.50 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = 3.12 × 10¹². (b) I = Q/t = 0.50 × 10⁻⁶ ÷ 1.0 × 10⁻⁶ = 0.50 A. Mark scheme (4 marks). C1: N = Q/e. C1: µC and µs converted. C1: I = Q/t. A1: I = 0.50 A.', 4, NULL, NULL),
('052c6b56-2bd6-5164-b397-35346944df0f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 33, 33, 'Why does a road tanker carrying fuel have a conducting strap connecting its body to the ground?', NULL, 2, 'multiple_choice'::answer_type, 'Friction of the flowing fuel can charge the tanker, and the strap lets charge flow to earth before a spark can ignite the fuel', NULL, false, NULL, false, NULL, 'Charge builds up by friction; earthing prevents a large potential difference and sparking. Mark scheme (3 marks). C1: charge builds up by friction. C1: earthing prevents sparks. A1: D (Friction of the flowing fuel can charge the tanker, and the strap lets charge flow to earth before a spark can ignite the fuel).', 3, NULL, NULL),
('3517ac76-c122-54b5-89ec-daa8eb3bf650', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 34, 34, 'Two identical metal spheres carry +8.0 nC and −2.0 nC. They are touched together and separated. Calculate the number of electrons that move from one sphere to the other. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.125e10', NULL, false, NULL, false, NULL, 'Each ends with (8.0 − 2.0) ÷ 2 = 3.0 nC. The first sphere changes from +8.0 nC to +3.0 nC, so it gains 5.0 nC of electrons: N = 5.0 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = 3.13 × 10¹⁰. Mark scheme (3 marks). C1: final charge 3.0 nC each. C1: change of 5.0 nC. A1: N = 3.13 × 10¹⁰.', 3, NULL, NULL),
('5b06b74e-62ef-55f5-a421-36630b8ba020', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 35, 35, 'An object has a charge of −3.2 µC. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'It has 2.0 × 10¹³ more electrons than protons', NULL, false, NULL, false, NULL, 'Excess = 3.2 × 10⁻⁶ ÷ 1.6 × 10⁻¹⁹ = 2.0 × 10¹³; a negative charge means extra electrons. Mark scheme (3 marks). C1: N = Q/e. C1: negative means excess electrons. A1: B (It has 2.0 × 10¹³ more electrons than protons).', 3, NULL, NULL),
('28f9e755-5290-5cfe-9e00-c3b03da8fe6d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 36, 36, 'An electron beam in a vacuum tube carries a current of 2.0 mA. Calculate the number of electrons passing a point each second. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.25e16', 's⁻¹', false, NULL, false, NULL, 'N per second = I/e = 2.0 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 1.25 × 10¹⁶ s⁻¹. Mark scheme (3 marks). C1: I = Ne/t. C1: substitution. A1: rate = 1.25 × 10¹⁶ s⁻¹.', 3, NULL, NULL),
('453b2903-1006-5a62-8f22-22252f7009bb', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 37, 37, 'After a polythene rod is rubbed with a cloth, the rod has a charge of −40 nC. Assuming no charge is lost to the surroundings, what is the charge on the cloth?', NULL, 2, 'multiple_choice'::answer_type, '+40 nC', NULL, false, NULL, false, NULL, 'Charge is conserved: the electrons gained by the rod came from the cloth, so the cloth has +40 nC. Mark scheme (4 marks). C1: charge conserved. C1: electrons transferred from cloth. C1: equal and opposite. A1: C (+40 nC).', 4, NULL, NULL),
('e7e3541e-393c-5344-904c-68bba1bb949d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 38, 38, 'A neutral metal sphere loses 5.0 × 10¹² electrons. Calculate its charge in µC. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.8 uC', 'µC', false, NULL, true, NULL, 'Q = Ne = 5.0 × 10¹² × 1.60 × 10⁻¹⁹ = 8.00 × 10⁻⁷ C. In µC: 8.00 × 10⁻⁷ × 10⁶ = +0.80. It is positive because electrons were lost. Mark scheme (3 marks). C1: Q = Ne. C1: sign and unit. A1: Q = 0.80 µC.', 3, NULL, NULL),
('86d4d4b8-1166-5897-a282-489a80795546', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 39, 39, 'A charged balloon stuck to a wall eventually falls off. What is the most likely reason?', NULL, 2, 'multiple_choice'::answer_type, 'Its charge slowly leaks away to the air and the wall, especially when the air is damp', NULL, false, NULL, false, NULL, 'Moist air and surface films conduct slightly, so the charge, and the induced attraction, decrease. Mark scheme (3 marks). C1: charge leaks away. C1: attraction decreases. A1: A (Its charge slowly leaks away to the air and the wall, especially when the air is damp).', 3, NULL, NULL),
('61378c0a-9275-5a4b-9b54-6d98d4c413dd', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 40, 40, 'A rod gains a charge of −5.0 µC by friction. Calculate the increase in its mass due to the extra electrons, in units of 10⁻¹⁷ kg. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '2.847', '10⁻¹⁷ kg', false, NULL, false, NULL, 'N = 5.0 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = 3.13 × 10¹³. Δm = 3.125 × 10¹³ × 9.11 × 10⁻³¹ = 2.85 × 10⁻¹⁷ kg. Mark scheme (3 marks). C1: N = Q/e. C1: Δm = N × mₑ. A1: Δm = 2.85 × 10⁻¹⁷ kg.', 3, NULL, NULL),
('ddad3da7-e2e4-53c5-85a2-a92409b52546', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 41, 41, 'Two touching, uncharged metal spheres A and B stand on insulating bases. A positively charged rod is held near A. The spheres are pulled apart and then the rod is removed. What are the charges on A and B?', NULL, 2, 'multiple_choice'::answer_type, 'A is negative and B is positive, with equal magnitudes', NULL, false, NULL, false, NULL, 'Electrons are attracted towards the rod into A; separating the spheres traps this distribution. Total charge stays zero. Mark scheme (3 marks). C1: electrons move to A. C1: equal and opposite, total zero. A1: D (A is negative and B is positive, with equal magnitudes).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 230" role="img" aria-labelledby="fgaf0a9615-t fgaf0a9615-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaf0a9615-t">Induction with two spheres</title><desc id="fgaf0a9615-d">Two touching, uncharged metal spheres A and B on insulating bases, with a positively charged rod held near A.</desc><circle cx="182" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="182" y1="148" x2="182" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="190" x2="204" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="182" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><circle cx="238" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="238" y1="148" x2="238" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="190" x2="260" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="238" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text><rect x="82" y="50" width="16" height="120" rx="4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="66" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="90" y="94" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="90" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="90" y="150" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text></svg>', 'Two touching, uncharged metal spheres A and B on insulating bases, with a positively charged rod held near A.'),
('d1a789d3-e5bc-5afe-82a6-faedb1b853c7', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 42, 42, 'Four identical metal spheres A, B, C and D are on insulating stands. A carries +16 nC, B carries −4.0 nC, and C and D are uncharged. In turn: A touches B; A touches C; C touches D. The spheres are separated after each contact. (a) Calculate the charge on A after it touches B. (b) Calculate the charges on A and on C after they touch. (c) Calculate the final charge on C. (d) Show that the total charge at the end equals the total at the start. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.5 nC', 'nC', false, NULL, false, NULL, '(a) A and B share (16 − 4.0) = 12 nC: each 12 ÷ 2 = 6.0 nC. (b) A and C share 6.0 nC: each 6.0 ÷ 2 = 3.0 nC. (c) C and D share 3.0 nC: each 3.0 ÷ 2 = 1.5 nC. (d) Final total = 3.0 + 6.0 + 1.5 + 1.5 = 12 nC, the same as 16 − 4.0 at the start. Mark scheme (6 marks). C1: equal sharing for identical spheres. C1: A after B = 6.0 nC. C1: A and C = 3.0 nC. B1: total 12 nC conserved. M1: signs combined correctly at the first contact. A1: Q_C = 1.5 nC.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 230" role="img" aria-labelledby="fgbffd7943-t fgbffd7943-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbffd7943-t">Four spheres</title><desc id="fgbffd7943-d">Four identical metal spheres on insulating stands: A carries +16 nC, B carries −4.0 nC, and C and D are uncharged.</desc><circle cx="77" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="77" y1="148" x2="77" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="55" y1="190" x2="99" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="77" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><text x="77" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+16 nC</text><circle cx="179" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="179" y1="148" x2="179" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="190" x2="201" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="179" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text><text x="179" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">−4.0 nC</text><circle cx="281" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="281" y1="148" x2="281" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="259" y1="190" x2="303" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="281" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">C</text><text x="281" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">uncharged</text><circle cx="383" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="383" y1="148" x2="383" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="361" y1="190" x2="405" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="383" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">D</text><text x="383" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">uncharged</text></svg>', 'Four identical metal spheres on insulating stands: A carries +16 nC, B carries −4.0 nC, and C and D are uncharged.'),
('4d4f702e-1e23-5ef0-84e8-bb6c1382e68d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 43, 43, 'The base of a thundercloud carries −30 C. In one lightning flash lasting 0.20 ms, 75 % of this charge flows to the ground. (a) Calculate the charge transferred. (b) Calculate the average current in the flash. (c) Calculate the number of electrons transferred. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.125e5', 'A', false, NULL, false, NULL, '(a) Q = 0.75 × 30 = 22.5 C. (b) I = Q/t = 22.5 ÷ 0.20 × 10⁻³ = 1.12 × 10⁵ A. (c) N = 22.5 ÷ 1.60 × 10⁻¹⁹ = 1.41 × 10²⁰. Mark scheme (5 marks). C1: 75 % of 30 C. C1: I = Q/t. C1: t in s. C1: N = Q/e. A1: I = 1.12 × 10⁵ A.', 5, NULL, NULL),
('c3a32d6c-6e3b-5e9e-864a-f83f247d6af8', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 44, 44, 'An electrostatic precipitator in a power-station chimney gives each smoke particle a charge of 5.0 × 10⁴ electrons. The charged particles are then attracted to earthed collecting plates. The precipitator removes 2.0 × 10¹⁰ particles each second. (a) Calculate the charge on one particle. (b) Calculate the current carried to the collecting plates, in mA. (c) Explain why the particles are attracted to the earthed plates even though the plates are uncharged at first. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.16 mA', 'mA', false, NULL, false, NULL, '(a) q = 5.0 × 10⁴ × 1.60 × 10⁻¹⁹ = 8.00 × 10⁻¹⁵ C. (b) I = 2.0 × 10¹⁰ × 8.00 × 10⁻¹⁵ = 1.60 × 10⁻⁴ A. In mA: 1.600 × 10⁻⁴ × 1000 = 0.160. (c) The charged particles induce opposite charge on the near surface of the earthed plates, and electrons can flow to or from earth, so there is always attraction. Mark scheme (6 marks). C1: q = Ne. C1: I = rate × q. C1: conversion to mA. B1: induced opposite charge. B1: earth supplies or removes electrons. A1: I = 0.160 mA.', 6, NULL, NULL),
('79de9294-917b-5a52-8853-ae32d6e96edf', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 45, 45, 'A balloon is rubbed on a person''s hair and gains a charge of −0.40 µC. (a) Calculate the number of electrons transferred. (b) State the charge on the hair. (c) Explain why the hairs stand apart from each other. Give only the answer to (a). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2.5e12', NULL, false, NULL, false, NULL, '(a) N = 0.40 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = 2.50 × 10¹². (b) +0.40 µC, because charge is conserved. (c) Each hair loses electrons and is positively charged; like charges repel, so the hairs push apart. Mark scheme (5 marks). C1: N = Q/e. B1: +0.40 µC on hair. B1: hairs have like charges. B1: like charges repel. A1: N = 2.50 × 10¹².', 5, NULL, NULL),
('ca039160-95f2-5d9e-b4e2-d09ef23281bb', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 46, 46, 'A metal sphere on an insulating stand is charged by induction using a rod carrying +20 nC. While the rod is held near, the sphere is connected to earth and then disconnected; the rod is then removed. The sphere is left with a charge of −8.0 nC. (a) State the direction in which electrons flowed through the earth connection. (b) Calculate the number of electrons that flowed. (c) Explain why the sphere''s charge is smaller in magnitude than the rod''s. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '5e10', NULL, false, NULL, false, NULL, '(a) From the earth to the sphere, attracted by the positive rod. (b) N = 8.0 × 10⁻⁹ ÷ 1.60 × 10⁻¹⁹ = 5.00 × 10¹⁰. (c) The rod is some distance away, so only part of its field ends on the sphere and fewer electrons are drawn up than would exactly balance it. Mark scheme (5 marks). B1: electrons flow from earth to sphere. C1: N = Q/e. C1: substitution. B1: rod not touching, so induced charge smaller. A1: N = 5.0 × 10¹⁰.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fg7b492dc0-t fg7b492dc0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7b492dc0-t">Charging by induction</title><desc id="fg7b492dc0-d">A metal sphere on an insulating stand with a rod carrying +20 nC held near it; the sphere is connected to earth and then disconnected.</desc><circle cx="180" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="148" x2="180" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="158" y1="190" x2="202" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="80" y="50" width="16" height="120" rx="4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="66" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="94" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="88" y="150" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><line x1="199.6" y1="139.6" x2="230" y2="180" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="180" x2="244" y2="180" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221" y1="185" x2="239" y2="185" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="190" x2="234" y2="190" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A metal sphere on an insulating stand with a rod carrying +20 nC held near it; the sphere is connected to earth and then disconnected.'),
('d11a820c-ebb8-5cf1-8de1-df9f802109e6', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 47, 47, 'A small metal sphere carries +64 nC. It is touched with an identical uncharged sphere, which is then earthed to remove its charge. This is repeated. (a) Show that after n contacts the charge on the first sphere is 64/2ⁿ nC. (b) Calculate the charge after 5 contacts. (c) Calculate the number of contacts needed before the charge first falls below 1.0 nC. (d) Explain why the halving process cannot continue for ever. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2 nC', 'nC', false, NULL, false, NULL, '(a) Each contact shares the charge equally, halving it, so after n contacts Q = 64 ÷ 2ⁿ nC. (b) Q = 64 ÷ 2⁵ = 2.0 nC. (c) 64 ÷ 2⁶ = 1.0 nC is not below 1.0 nC, but 64 ÷ 2⁷ = 0.50 nC is, so 7 contacts. (d) Charge is quantised in units of e = 1.6 × 10⁻¹⁹ C, so the charge cannot be shared into amounts smaller than one electron''s charge. Mark scheme (6 marks). M1: charge halves at each contact. C1: 64/2⁵. C1: 2⁶ gives 1.0 nC. A1: 7 contacts. B1: charge quantised in units of e. A1: Q = 2.0 nC.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 230" role="img" aria-labelledby="fg3c02aef9-t fg3c02aef9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3c02aef9-t">Repeated sharing</title><desc id="fg3c02aef9-d">A small metal sphere carrying +64 nC and an identical uncharged sphere, which is earthed after each contact.</desc><circle cx="159" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="148" x2="159" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="137" y1="190" x2="181" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="159" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+64 nC</text><circle cx="261" cy="120" r="28" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="261" y1="148" x2="261" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="239" y1="190" x2="283" y2="190" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="261" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">uncharged</text><line x1="280.6" y1="139.6" x2="311" y2="180" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="297" y1="180" x2="325" y2="180" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="302" y1="185" x2="320" y2="185" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="307" y1="190" x2="315" y2="190" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A small metal sphere carrying +64 nC and an identical uncharged sphere, which is earthed after each contact.'),
('633fbc2d-af51-5504-be59-77eb5ded325e', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 48, 48, 'The electron gun in an old television tube produced a beam current of 0.80 mA. It ran for 2.0 hours. (a) Calculate the charge carried by the beam. (b) Calculate the number of electrons. (c) Calculate the total mass of these electrons, in units of 10⁻¹¹ kg. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '3.28', '10⁻¹¹ kg', false, NULL, false, NULL, '(a) Q = It = 0.80 × 10⁻³ × 7200 = 5.76 C. (b) N = 5.76 ÷ 1.60 × 10⁻¹⁹ = 3.60 × 10¹⁹. (c) m = 3.600 × 10¹⁹ × 9.11 × 10⁻³¹ = 3.28 × 10⁻¹¹ kg. Mark scheme (5 marks). C1: Q = It. C1: t = 7200 s. C1: N = Q/e. C1: m = Nmₑ. A1: m = 3.28 × 10⁻¹¹ kg.', 5, NULL, NULL),
('cce01133-e7ef-545c-9a6b-b3f8e3347245', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 49, 49, 'A crop sprayer charges each droplet to 2.0 × 10⁻¹² C and emits 4.0 × 10⁸ droplets per second. (a) Calculate the current carried by the spray, in mA. (b) Explain why the droplets spread out into a wide cloud. (c) Explain why charged droplets coat the undersides of leaves as well as the tops. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.8 mA', 'mA', false, NULL, false, NULL, '(a) I = 4.0 × 10⁸ × 2.0 × 10⁻¹² = 8.00 × 10⁻⁴ A. In mA: 8.0 × 10⁻⁴ × 1000 = 0.80. (b) All the droplets carry the same sign of charge, so they repel each other. (c) The plants are earthed, so the droplets induce opposite charge on them and are attracted to all surfaces, curving round to the undersides. Mark scheme (5 marks). C1: I = rate × charge. C1: conversion to mA. B1: like charges repel. B1: induced charge on earthed plant. A1: I = 0.80 mA.', 5, NULL, NULL),
('d346f32a-2ba7-570c-9238-0f50290203dc', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '49460917-aba1-4426-8cf1-21b78854f490', 'a-level', '21.1', '9702 coursebook 21.1 · Attraction and repulsion', 50, 50, 'In an experiment like Millikan''s, a student measures the charges on four oil drops as 4.9, 8.1, 11.3 and 16.0 × 10⁻¹⁹ C, each with an uncertainty of about ±0.2 × 10⁻¹⁹ C. (a) Divide each value by 1.6 × 10⁻¹⁹ C and comment on the results. (b) State the number of electronic charges on each drop. (c) Use all four results to calculate a value for the elementary charge, in units of 10⁻¹⁹ C. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.612', '10⁻¹⁹ C', false, NULL, false, NULL, '(a) 4.9 ÷ 1.6 = 3.06, 8.1 ÷ 1.6 = 5.06, 11.3 ÷ 1.6 = 7.06 and 16.0 ÷ 1.6 = 10.0: all close to whole numbers within the uncertainty. (b) 3, 5, 7 and 10. (c) e = total charge ÷ total number of electrons: (4.9 + 8.1 + 11.3 + 16.0) × 10⁻¹⁹ ÷ (3 + 5 + 7 + 10) = 1.61 × 10⁻¹⁹ C. Mark scheme (6 marks). C1: ratios calculated. B1: close to integers. B1: 3, 5, 7, 10. M1: total charge ÷ total number. C1: substitution. A1: e = 1.61 × 10⁻¹⁹ C.', 6, NULL, NULL)
