INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('5bb2e955-809f-5369-bc3d-e7aa0fd32162', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 9, 9, 'Which is the definition of electric field strength at a point?', NULL, 1, 'multiple_choice'::answer_type, 'The force per unit positive charge on a small charge placed at that point', NULL, false, NULL, false, NULL, 'E = F/Q for a small positive test charge. Mark scheme (1 mark). B1: C (The force per unit positive charge on a small charge placed at that point).', 1, NULL, NULL),
('57ae07ee-db5b-5e6a-8b27-6bd23ce25775', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 10, 10, 'Which unit is a correct unit for electric field strength?', NULL, 1, 'multiple_choice'::answer_type, 'N C⁻¹', NULL, false, NULL, false, NULL, 'E = F/Q, so N C⁻¹; this is equivalent to V m⁻¹. Mark scheme (1 mark). B1: A (N C⁻¹).', 1, NULL, NULL),
('fd982a4e-5e67-5b18-b2ac-16db5319a78c', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 11, 11, 'A proton is at a point where the electric field strength is 2.5 × 10⁴ N C⁻¹. Calculate the force on it, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4', '10⁻¹⁵ N', false, NULL, false, NULL, 'F = EQ = 2.5 × 10⁴ × 1.60 × 10⁻¹⁹ = 4.00 × 10⁻¹⁵ N. Mark scheme (2 marks). C1: F = EQ. A1: F = 4.0 × 10⁻¹⁵ N.', 2, NULL, NULL),
('2fd90e6f-ad10-54dc-a710-eec2fafe5f89', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 12, 12, 'A dust particle with charge +3.0 nC experiences an electric force of 6.0 × 10⁻⁵ N. Calculate the electric field strength at its position.', NULL, 1, 'numeric'::answer_type, '20000', 'N C⁻¹', false, NULL, false, NULL, 'E = F/Q = 6.0 × 10⁻⁵ ÷ 3.0 × 10⁻⁹ = 2.0 × 10⁴ N C⁻¹. Mark scheme (2 marks). C1: E = F/Q with Q in C. A1: E = 2.0 × 10⁴ N C⁻¹.', 2, NULL, NULL),
('60958636-19e4-50c2-9444-2a85af583b02', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 13, 13, 'Which describes the field lines around an isolated positive point charge?', NULL, 1, 'multiple_choice'::answer_type, 'Straight lines pointing radially outwards', NULL, false, NULL, false, NULL, 'Field lines show the direction of the force on a positive test charge: away from a positive charge. Mark scheme (1 mark). B1: D (Straight lines pointing radially outwards).', 1, NULL, NULL),
('5bd4614f-60a6-5341-8903-d4cc7390bef1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 14, 14, 'On an electric field diagram, what does the spacing of the field lines show?', NULL, 1, 'multiple_choice'::answer_type, 'The field strength: closer lines mean a stronger field', NULL, false, NULL, false, NULL, 'Line density is proportional to field strength. Mark scheme (1 mark). B1: B (The field strength: closer lines mean a stronger field).', 1, NULL, NULL),
('937d6492-b2ac-5c39-8f64-3d6ee9253404', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 15, 15, 'A charge of −5.0 µC is placed in a uniform electric field of strength 800 N C⁻¹. Calculate the magnitude of the force on it.', NULL, 1, 'numeric'::answer_type, '0.004', 'N', false, NULL, false, NULL, 'F = EQ = 800 × 5.0 × 10⁻⁶ = 4.0 × 10⁻³ N, directed opposite to the field. Mark scheme (2 marks). C1: F = EQ. A1: F = 0.0040 N.', 2, NULL, NULL),
('eb254b92-5d8f-5298-9418-4a19a398b402', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 16, 16, 'The electric field at a point is directed due east. In which direction is the force on an electron at that point?', NULL, 1, 'multiple_choice'::answer_type, 'Due west', NULL, false, NULL, false, NULL, 'Field direction is the force direction on a positive charge; the electron is negative. Mark scheme (1 mark). B1: C (Due west).', 1, NULL, NULL),
('2ca34e3b-7e3b-50fb-ab19-2eba933e8ffc', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 17, 17, 'Two equal positive point charges are some distance apart. Where is the electric field zero?', NULL, 1, 'multiple_choice'::answer_type, 'At the midpoint between them', NULL, false, NULL, false, NULL, 'At the midpoint the equal fields from the two charges are opposite and cancel: a neutral point. Mark scheme (1 mark). B1: A (At the midpoint between them).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 160" role="img" aria-labelledby="fg3b2e7691-t fg3b2e7691-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3b2e7691-t">Two equal positive charges</title><desc id="fg3b2e7691-d">Two equal positive point charges a short distance apart.</desc><circle cx="110" cy="80" r="13" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="110" y="80.5" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="110" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+Q</text><circle cx="310" cy="80" r="13" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="310" y="80.5" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="310" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+Q</text></svg>', 'Two equal positive point charges a short distance apart.'),
('baeb5f3f-8c21-5c8c-a6c6-e8bfbe5ed587', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 18, 18, 'An oil droplet carrying a charge of 4.8 × 10⁻¹⁹ C experiences an electric force of 2.4 × 10⁻¹⁴ N. Calculate the field strength.', NULL, 1, 'numeric'::answer_type, '50000', 'N C⁻¹', false, NULL, false, NULL, 'E = F/Q = 2.4 × 10⁻¹⁴ ÷ 4.8 × 10⁻¹⁹ = 5.0 × 10⁴ N C⁻¹. Mark scheme (2 marks). C1: E = F/Q. A1: E = 5.0 × 10⁴ N C⁻¹.', 2, NULL, NULL),
('c4d9e786-bce0-50a7-a192-6be81d4a8068', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 19, 19, 'At what angle do electric field lines meet the surface of a charged conductor?', NULL, 1, 'multiple_choice'::answer_type, 'At right angles', NULL, false, NULL, false, NULL, 'There is no field component along the surface of a conductor in equilibrium, or charges would move. Mark scheme (1 mark). B1: D (At right angles).', 1, NULL, NULL),
('8609523a-ce84-5b70-8db4-6db2522104dc', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 20, 20, 'Why is electric field strength a vector quantity?', NULL, 1, 'multiple_choice'::answer_type, 'It has both magnitude and direction', NULL, false, NULL, false, NULL, 'E has the direction of the force on a positive charge. Mark scheme (1 mark). B1: B (It has both magnitude and direction).', 1, NULL, NULL),
('4599f81c-0091-5351-a03e-57a801c4385c', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 21, 21, 'At a certain point the electric field strength is 1.2 × 10⁵ N C⁻¹. What charge would experience a force of 0.36 N there? Give your answer in µC.', NULL, 1, 'numeric'::answer_type, '3 uC', 'µC', false, NULL, false, NULL, 'Q = F/E = 0.36 ÷ 1.2 × 10⁵ = 3.0 × 10⁻⁶ C. In µC: 3.0 × 10⁻⁶ × 10⁶ = 3.0. Mark scheme (2 marks). C1: Q = F/E. A1: Q = 3.0 µC.', 2, NULL, NULL),
('af521e90-4eed-5765-99ec-298edb87abb4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 22, 22, 'Which statement about gravitational and electric fields is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Gravitational forces are always attractive, but electric forces can attract or repel', NULL, false, NULL, false, NULL, 'Mass is always positive; charge can be positive or negative. Mark scheme (1 mark). B1: C (Gravitational forces are always attractive, but electric forces can attract or repel).', 1, NULL, NULL),
('1df5b877-c0ce-5647-b9ba-450a5337f094', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 23, 23, 'A charge experiences a force of 2.0 mN in an electric field. The field strength is tripled. What is the new force, in mN?', NULL, 1, 'numeric'::answer_type, '6 mN', 'mN', false, NULL, false, NULL, 'F = EQ, so tripling E triples F: 3 × 2.0 = 6.0 mN. Mark scheme (1 mark). A1: F = 6.0 mN.', 1, NULL, NULL),
('89b876d3-4417-515d-af6c-4af9491790f0', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 24, 24, 'At point P, one charged object produces a field of 3.0 × 10⁴ N C⁻¹ due east and a second produces a field of 4.0 × 10⁴ N C⁻¹ due north. Calculate the magnitude of the resultant field at P.', NULL, 2, 'numeric'::answer_type, '50000', 'N C⁻¹', false, NULL, false, NULL, 'Fields add as vectors: E = √((3.0 × 10⁴)² + (4.0 × 10⁴)²) = 5.0 × 10⁴ N C⁻¹. Mark scheme (3 marks). M1: vector addition at right angles. C1: Pythagoras. A1: E = 5.0 × 10⁴ N C⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fg3d6823a7-t fg3d6823a7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3d6823a7-t">Two fields at P</title><desc id="fg3d6823a7-d">Vector diagram at point P (north up the page): a field of 3.0 × 10⁴ N C⁻¹ due east and a field of 4.0 × 10⁴ N C⁻¹ due north.</desc><line x1="70" y1="180" x2="153.7" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="160,180 151.8,183.8 151.8,176.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="174" y="180" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 × 10⁴ N C⁻¹ east</text><line x1="70" y1="180" x2="70" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="70,60 73.8,68.2 66.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="70" y="46" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.0 × 10⁴ N C⁻¹ north</text><circle cx="70" cy="180" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Vector diagram at point P (north up the page): a field of 3.0 × 10⁴ N C⁻¹ due east and a field of 4.0 × 10⁴ N C⁻¹ due north.'),
('fc4beb8e-3561-57d5-a5d0-5386796769ec', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 25, 25, 'At a point, charge A produces a field of 6.0 × 10³ N C⁻¹ due east and charge B produces a field of 2.5 × 10³ N C⁻¹ due west. Calculate the magnitude of the force on an electron at this point, in units of 10⁻¹⁶ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.6', '10⁻¹⁶ N', false, NULL, false, NULL, 'Resultant E = 6.0 × 10³ − 2.5 × 10³ = 3.5 × 10³ N C⁻¹ east. F = 3.5 × 10³ × 1.60 × 10⁻¹⁹ = 5.60 × 10⁻¹⁶ N, directed west. Mark scheme (3 marks). C1: opposite fields subtract. C1: F = EQ. A1: F = 5.6 × 10⁻¹⁶ N.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 200" role="img" aria-labelledby="fg6d7c795d-t fg6d7c795d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6d7c795d-t">Opposite fields</title><desc id="fg6d7c795d-d">Vector diagram at the point: charge A gives a field of 6.0 × 10³ N C⁻¹ due east and charge B gives 2.5 × 10³ N C⁻¹ due west.</desc><line x1="185" y1="110" x2="298.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="305,110 296.8,113.8 296.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="319" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">6.0 × 10³ N C⁻¹ east</text><line x1="185" y1="110" x2="141.3" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="135,110 143.2,106.2 143.2,113.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="121" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">2.5 × 10³ N C⁻¹ west</text><circle cx="185" cy="110" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Vector diagram at the point: charge A gives a field of 6.0 × 10³ N C⁻¹ due east and charge B gives 2.5 × 10³ N C⁻¹ due west.'),
('5b48eee7-3be2-548f-89c5-59d02330b6b4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 26, 26, 'A positive point charge is held above a large, flat, earthed metal plate. Which describes the field lines near the plate?', NULL, 2, 'multiple_choice'::answer_type, 'They curve from the charge and meet the plate at right angles', NULL, false, NULL, false, NULL, 'Lines start on the positive charge and end on induced negative charge on the plate, always perpendicular to a conductor''s surface. Mark scheme (3 marks). C1: lines end on induced charge. C1: perpendicular to conductor. A1: A (They curve from the charge and meet the plate at right angles).', 3, NULL, NULL),
('de525e47-4db3-571d-8c89-ea105a588b01', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 27, 27, 'A small charged sphere of mass 2.0 × 10⁻⁴ kg hangs from an insulating thread in a uniform horizontal electric field of 4.0 × 10⁴ N C⁻¹. The thread makes an angle of 15° with the vertical. Calculate the charge on the sphere, in nC. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '13.14 nC', 'nC', false, NULL, false, NULL, 'Horizontally T sin 15° = QE and vertically T cos 15° = mg, so QE = mg tan 15°. Q = 2.0 × 10⁻⁴ × 9.81 × tan 15° ÷ 4.0 × 10⁴ = 1.31 × 10⁻⁸ C. In nC: 1.314 × 10⁻⁸ × 10⁹ = 13.1. Mark scheme (4 marks). M1: resolve forces. C1: QE = mg tan θ. C1: substitution. A1: Q = 13.1 nC.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 270" role="img" aria-labelledby="fgb31bd442-t fgb31bd442-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb31bd442-t">Charged sphere in a field</title><desc id="fgb31bd442-d">A small charged sphere of mass 2.0 × 10⁻⁴ kg hangs from an insulating thread in a uniform horizontal field of 4.0 × 10⁴ N C⁻¹; the thread makes 15° with the vertical. Forces: tension T, weight W and electric force F.</desc><line x1="70" y1="30" x2="170" y2="30" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="30" x2="67" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="30" x2="85" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111" y1="30" x2="103" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129" y1="30" x2="121" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="30" x2="139" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165" y1="30" x2="157" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="30" x2="120" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 4"/><line x1="120" y1="30" x2="158.8" y2="174.9" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M120,70 A40,40 0 0,0 130.4,68.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="137.9" y="87.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">15°</text><circle cx="158.8" cy="174.9" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="155.7" y1="163.3" x2="141.8" y2="111.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140.2,105.3 146,112.2 138.6,114.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="161.5" y="132.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">T</text><line x1="158.8" y1="186.9" x2="158.8" y2="238.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="158.8,244.9 155,236.7 162.6,236.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="168.8" y="240.9" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">W</text><line x1="170.8" y1="174.9" x2="222.5" y2="174.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="228.8,174.9 220.7,178.7 220.7,171.1" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="234.8" y="174.9" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">F</text><line x1="20" y1="252" x2="84.4" y2="252" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="90,252 82.7,255.4 82.7,248.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="98" y="252" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E = 4.0 × 10⁴ N C⁻¹</text></svg>', 'A small charged sphere of mass 2.0 × 10⁻⁴ kg hangs from an insulating thread in a uniform horizontal field of 4.0 × 10⁴ N C⁻¹; the thread makes 15° with the vertical. Forces: tension T, weight W and electric force F.'),
('f9eba46c-77ac-5fd7-a634-7866f31df850', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 28, 28, 'A pear-shaped metal conductor is charged. Where is the electric field just outside its surface strongest?', NULL, 2, 'multiple_choice'::answer_type, 'Near the most sharply curved, pointed end', NULL, false, NULL, false, NULL, 'Charge concentrates where curvature is greatest, so field lines are densest there; this is why lightning conductors are pointed. Mark scheme (3 marks). C1: charge density highest at points. C1: field lines densest. A1: D (Near the most sharply curved, pointed end).', 3, NULL, NULL),
('fb0fd43a-69ff-594a-bac1-b97a1557133f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 29, 29, 'An α-particle (charge +2e, mass 6.64 × 10⁻²⁷ kg) is in an electric field of 2.0 × 10⁵ N C⁻¹. Calculate its acceleration. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '9.639e12', 'm s⁻²', false, NULL, false, NULL, 'F = 2eE = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = 6.40 × 10⁻¹⁴ N. a = F/m = 6.40 × 10⁻¹⁴ ÷ 6.64 × 10⁻²⁷ = 9.64 × 10¹² m s⁻². Mark scheme (3 marks). C1: charge = 2e. C1: a = F/m. A1: a = 9.64 × 10¹² m s⁻².', 3, NULL, NULL),
('95dc985a-494f-549c-83b6-a895603420d6', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 30, 30, 'A positive test charge is placed near a negatively charged sphere. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The field lines point towards the sphere and the test charge is pulled towards it', NULL, false, NULL, false, NULL, 'Lines end on negative charge, and a positive charge moves along the field direction. Mark scheme (3 marks). C1: lines end on negative charge. C1: positive charge moves along E. A1: B (The field lines point towards the sphere and the test charge is pulled towards it).', 3, NULL, NULL),
('4f7d5877-001d-5759-bd75-76b8182356b6', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 31, 31, 'A dust particle of mass 1.0 × 10⁻¹² kg carries 50 excess electrons. It is in an electric field of 2.0 × 10⁴ N C⁻¹. Ignoring gravity and air resistance, calculate its acceleration. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.16', 'm s⁻²', false, NULL, false, NULL, 'Q = 50 × 1.60 × 10⁻¹⁹ = 8.00 × 10⁻¹⁸ C. F = EQ = 2.0 × 10⁴ × 8.00 × 10⁻¹⁸ = 1.60 × 10⁻¹³ N. a = 1.60 × 10⁻¹³ ÷ 1.0 × 10⁻¹² = 0.160 m s⁻². Mark scheme (4 marks). C1: Q = Ne. C1: F = EQ. C1: a = F/m. A1: a = 0.16 m s⁻².', 4, NULL, NULL),
('84f3343b-0e98-5d7d-883c-56878b30d9ea', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 32, 32, 'Why should the test charge used to measure an electric field be very small?', NULL, 2, 'multiple_choice'::answer_type, 'So that it does not disturb the charges that produce the field being measured', NULL, false, NULL, false, NULL, 'A large test charge would push or pull the source charges, changing the field it was meant to measure. Mark scheme (4 marks). C1: test charge exerts forces too. C1: source charges could move. C1: field would change. A1: C (So that it does not disturb the charges that produce the field being measured).', 4, NULL, NULL),
('c5d56323-fbdb-5b29-9139-cf74499431cf', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 33, 33, 'Near the Earth''s surface in fine weather there is an electric field of about 130 N C⁻¹. Calculate the ratio of the electric force on an electron in this field to the electron''s weight. Take e = 1.60 × 10⁻¹⁹ C, mₑ = 9.11 × 10⁻³¹ kg and g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '2.327e12', NULL, false, NULL, false, NULL, 'F_E = 130 × 1.60 × 10⁻¹⁹ = 2.08 × 10⁻¹⁷ N. W = 9.11 × 10⁻³¹ × 9.81 = 8.94 × 10⁻³⁰ N. Ratio = 2.080 × 10⁻¹⁷ ÷ 8.937 × 10⁻³⁰ = 2.33 × 10¹². Mark scheme (3 marks). C1: F = eE. C1: W = mg. A1: ratio = 2.33 × 10¹².', 3, NULL, NULL),
('59697131-8779-5915-98e6-3c181922490b', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 34, 34, 'A positive and a negative point charge of equal magnitude are placed a short distance apart. What is the direction of the electric field at the midpoint between them?', NULL, 2, 'multiple_choice'::answer_type, 'Along the line joining them, towards the negative charge', NULL, false, NULL, false, NULL, 'Both fields point the same way at the midpoint: away from + and towards −, so they add. Mark scheme (3 marks). C1: both fields point the same way. C1: towards the negative charge. A1: A (Along the line joining them, towards the negative charge).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 160" role="img" aria-labelledby="fg33d4f92e-t fg33d4f92e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg33d4f92e-t">Opposite charges</title><desc id="fg33d4f92e-d">A positive and a negative point charge of equal magnitude a short distance apart, with M the midpoint between them.</desc><circle cx="110" cy="80" r="13" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="110" y="80.5" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="110" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">+Q</text><circle cx="310" cy="80" r="13" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="310" y="80.5" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8);font-weight:700">−</text><text x="310" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">−Q</text><circle cx="210" cy="80" r="3.6" style="fill:currentColor;stroke:none"/><text x="210" y="66" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">M</text></svg>', 'A positive and a negative point charge of equal magnitude a short distance apart, with M the midpoint between them.'),
('4a49f29a-2e53-5bfc-9c0d-5e95f18ea092', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 35, 35, 'A charge of +2.0 µC at point P experiences a force of 0.050 N to the left. The +2.0 µC charge is replaced by a charge of −6.0 µC. Calculate the magnitude of the force on the new charge.', NULL, 2, 'numeric'::answer_type, '0.15', 'N', false, NULL, false, NULL, 'E = F/Q = 0.050 ÷ 2.0 × 10⁻⁶ = 2.5 × 10⁴ N C⁻¹ to the left. F = 2.5 × 10⁴ × 6.0 × 10⁻⁶ = 0.15 N, to the right. Mark scheme (3 marks). C1: E = F/Q. C1: F = EQ for new charge. A1: F = 0.15 N.', 3, NULL, NULL),
('069b71af-04b8-524e-8b61-d9b31a838ac3', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 36, 36, 'Near the ground the Earth''s fair-weather electric field points vertically downwards. What does this show about the charge on the Earth''s surface?', NULL, 2, 'multiple_choice'::answer_type, 'It is negative', NULL, false, NULL, false, NULL, 'Field lines end on negative charge, so downward lines end on a negatively charged ground. Mark scheme (3 marks). C1: lines end on negative charge. C1: downward field. A1: D (It is negative).', 3, NULL, NULL),
('7de4e315-fa04-5234-9abf-bb6b4641afd9', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 37, 37, 'At a point, the electric field has a horizontal component of 2.0 × 10³ N C⁻¹ and a vertically upward component of 5.0 × 10³ N C⁻¹. Calculate the angle the resultant field makes with the horizontal.', NULL, 2, 'numeric'::answer_type, '68.2', '°', false, NULL, false, NULL, 'tan θ = 5.0 × 10³ ÷ 2.0 × 10³ = 2.5, so θ = tan⁻¹ 2.5 = 68.2°. Mark scheme (4 marks). M1: field components combine as vectors. C1: tan θ = E_y/E_x. C1: inverse tangent. A1: θ = 68.2°.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fgf68a3757-t fgf68a3757-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf68a3757-t">Field components</title><desc id="fgf68a3757-d">Vector diagram: a horizontal field component of 2.0 × 10³ N C⁻¹ and a vertically upward component of 5.0 × 10³ N C⁻¹ from the same point.</desc><line x1="80" y1="190" x2="153.7" y2="190" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="160,190 151.8,193.8 151.8,186.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="174" y="190" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 × 10³ N C⁻¹</text><line x1="80" y1="190" x2="80" y2="46.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="80,40 83.8,48.2 76.2,48.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="80" y="26" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">5.0 × 10³ N C⁻¹</text><circle cx="80" cy="190" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Vector diagram: a horizontal field component of 2.0 × 10³ N C⁻¹ and a vertically upward component of 5.0 × 10³ N C⁻¹ from the same point.'),
('09f14b74-d01d-5d10-b676-07bdd9b2511b', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 38, 38, 'Which describes the electric field near the middle of a large, flat, positively charged plate?', NULL, 2, 'multiple_choice'::answer_type, 'Parallel lines perpendicular to the plate, pointing away from it, equally spaced', NULL, false, NULL, false, NULL, 'Far from the edges, a large plate produces a uniform field perpendicular to its surface. Mark scheme (3 marks). C1: perpendicular, away from + plate. C1: uniform spacing. A1: B (Parallel lines perpendicular to the plate, pointing away from it, equally spaced).', 3, NULL, NULL),
('68e13f84-8cda-5724-ad90-223a3f83a32d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 39, 39, 'A small sphere of mass 3.0 × 10⁻⁴ kg carries a charge of +25 nC and hangs from an insulating thread. A uniform horizontal electric field is switched on and the thread settles at 10° to the vertical. (a) Draw and label the forces on the sphere (describe them in words). (b) Calculate the electric field strength. (c) Calculate the tension in the thread. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '20757', 'N C⁻¹', false, NULL, false, NULL, '(a) Weight mg downwards, tension T along the thread, and electric force QE horizontally in the direction of the field. (b) QE = mg tan 10°, so E = 3.0 × 10⁻⁴ × 9.81 × tan 10° ÷ 25 × 10⁻⁹ = 2.08 × 10⁴ N C⁻¹. (c) T = mg ÷ cos 10° = 3.0 × 10⁻⁴ × 9.81 ÷ cos 10° = 0.00299 N. Mark scheme (6 marks). B1: three forces identified. M1: resolve: QE = mg tan θ. C1: substitution with Q in C. C1: T = mg/cos θ. A1: tension value. A1: E = 2.08 × 10⁴ N C⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 270" role="img" aria-labelledby="fg9c647e34-t fg9c647e34-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9c647e34-t">Charged sphere in a field</title><desc id="fg9c647e34-d">A sphere of mass 3.0 × 10⁻⁴ kg carrying +25 nC hangs from an insulating thread in a uniform horizontal field; the thread settles at 10° to the vertical.</desc><line x1="70" y1="30" x2="170" y2="30" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="30" x2="67" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="30" x2="85" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111" y1="30" x2="103" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129" y1="30" x2="121" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="30" x2="139" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165" y1="30" x2="157" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="30" x2="120" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 4"/><line x1="120" y1="30" x2="146" y2="177.7" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M120,70 A40,40 0 0,0 126.9,69.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136.6" y="87.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">10°</text><circle cx="146" cy="177.7" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="144" y1="165.9" x2="134.6" y2="113" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="133.5,106.8 138.7,114.2 131.2,115.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="152.5" y="135.9" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">T</text><line x1="146" y1="189.7" x2="146" y2="241.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="146,247.7 142.2,239.6 149.9,239.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="156" y="243.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">W</text><line x1="158" y1="177.7" x2="209.7" y2="177.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="216,177.7 207.9,181.5 207.9,173.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="222" y="177.7" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">F</text><line x1="20" y1="252" x2="84.4" y2="252" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="90,252 82.7,255.4 82.7,248.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="98" y="252" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E</text></svg>', 'A sphere of mass 3.0 × 10⁻⁴ kg carrying +25 nC hangs from an insulating thread in a uniform horizontal field; the thread settles at 10° to the vertical.'),
('22924d6a-6fb3-5e32-86a8-33f1dc803976', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 40, 40, 'At point P, charge A produces an electric field of 8.0 × 10⁴ N C⁻¹ in the +x direction. Charge B produces a field of 6.0 × 10⁴ N C⁻¹ directed at 60° above the −x direction. (a) Calculate the x- and y-components of the resultant field. (b) Calculate the magnitude of the resultant field. (c) Calculate the magnitude of the force on an electron at P, in units of 10⁻¹⁵ N. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '72111', 'N C⁻¹', false, NULL, false, NULL, '(a) E_x = 8.0 × 10⁴ − 6.0 × 10⁴ × cos 60° = 5.0 × 10⁴ N C⁻¹. E_y = 6.0 × 10⁴ × sin 60° = 5.20 × 10⁴ N C⁻¹. (b) E = √((5.0 × 10⁴)² + (5.196 × 10⁴)²) = 7.21 × 10⁴ N C⁻¹. (c) F = 1.60 × 10⁻¹⁹ × 7.211 × 10⁴ = 1.15 × 10⁻¹⁴ N. Mark scheme (6 marks). C1: x-component. C1: y-component. M1: Pythagoras on components. C1: F = eE. A1: force value. A1: E = 7.21 × 10⁴ N C⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 230" role="img" aria-labelledby="fg40a17c61-t fg40a17c61-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg40a17c61-t">Two fields at P</title><desc id="fg40a17c61-d">Vector diagram at P: field A of 8.0 × 10⁴ N C⁻¹ along +x, and field B of 6.0 × 10⁴ N C⁻¹ at 60° above the −x direction.</desc><line x1="170" y1="170" x2="307.7" y2="170" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="314,170 305.8,173.8 305.8,166.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="328" y="170" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8.0 × 10⁴ N C⁻¹</text><line x1="170" y1="170" x2="119.2" y2="81.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="116,76.5 123.4,81.6 116.8,85.4" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="109" y="64.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 × 10⁴ N C⁻¹</text><circle cx="170" cy="170" r="3.4" style="fill:currentColor;stroke:none"/><path d="M152,138.8 A36,36 0 0,0 134,170" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="126.7" y="145" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60°</text></svg>', 'Vector diagram at P: field A of 8.0 × 10⁴ N C⁻¹ along +x, and field B of 6.0 × 10⁴ N C⁻¹ at 60° above the −x direction.'),
('a90d33c9-3298-50fc-a57a-da9277623ff2', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 41, 41, 'An electron and a proton are released from rest at the same point in a uniform electric field of 1.5 × 10³ N C⁻¹. (a) Compare the magnitudes and directions of the forces on them. (b) Calculate the acceleration of the electron. (c) Calculate the ratio (acceleration of electron) ÷ (acceleration of proton). Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C, mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '1833', NULL, false, NULL, false, NULL, '(a) Equal magnitudes, eE, in opposite directions: the proton along the field, the electron against it. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 1.5 × 10³ ÷ 9.11 × 10⁻³¹ = 2.63 × 10¹⁴ m s⁻². (c) Same force, so a ∝ 1/m: ratio = 1.67 × 10⁻²⁷ ÷ 9.11 × 10⁻³¹ = 1830. Mark scheme (5 marks). B1: equal and opposite forces. C1: a = eE/m. M1: same F so a ∝ 1/m. C1: mass ratio. A1: ratio = 1830.', 5, NULL, NULL),
('6e39b546-1b50-5382-9aa4-f53356a77614', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 42, 42, 'A probe measures the force on a test charge of 2.0 nC at different distances r from the centre of a charged sphere: r = 0.10, 0.20 and 0.30 m; F = 7.2 × 10⁻⁴, 1.8 × 10⁻⁴ and 8.0 × 10⁻⁵ N. (a) Calculate the field strength at each distance. (b) Show that the field strength is inversely proportional to r². (c) Predict the field strength at r = 0.40 m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '22500', 'N C⁻¹', false, NULL, false, NULL, '(a) E = F/q: 7.2 × 10⁻⁴ ÷ 2.0 × 10⁻⁹ = 3.6 × 10⁵ N C⁻¹; 1.8 × 10⁻⁴ ÷ 2.0 × 10⁻⁹ = 9.0 × 10⁴ N C⁻¹; 8.0 × 10⁻⁵ ÷ 2.0 × 10⁻⁹ = 4.0 × 10⁴ N C⁻¹. (b) Er² = 3.6 × 10⁵ × 0.10² = 3600 N m² C⁻¹ for every reading, so E ∝ 1/r². (c) E = 3600 ÷ 0.40² = 2.25 × 10⁴ N C⁻¹. Mark scheme (6 marks). C1: E = F/q for each reading. B1: Er² constant. M1: E ∝ 1/r². C1: substitution at 0.40 m. C1: field lines spread out, consistent with radial field. A1: E = 2.25 × 10⁴ N C⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg6339d477-t fg6339d477-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6339d477-t">Force against distance</title><desc id="fg6339d477-d">Graph of the force on a 2.0 nC test charge against distance from the centre of a charged sphere: 7.2 × 10⁻⁴ N at 0.10 m, 1.8 × 10⁻⁴ N at 0.20 m and 8.0 × 10⁻⁵ N at 0.30 m.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="126.3" y1="34" x2="126.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="228.6" y1="34" x2="228.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="330.9" y1="34" x2="330.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="126.3" y1="242" x2="126.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="126.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.1</text><line x1="228.6" y1="242" x2="228.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="228.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="330.9" y1="242" x2="330.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="330.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.3</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="190" x2="24" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="138" x2="24" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="86" x2="24" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r / m</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">F / 10⁻⁴ N</text><line x1="122.3" y1="50.8" x2="130.3" y2="58.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122.3" y1="58.8" x2="130.3" y2="50.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224.6" y1="191.2" x2="232.6" y2="199.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224.6" y1="199.2" x2="232.6" y2="191.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="326.9" y1="217.2" x2="334.9" y2="225.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="326.9" y1="225.2" x2="334.9" y2="217.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of the force on a 2.0 nC test charge against distance from the centre of a charged sphere: 7.2 × 10⁻⁴ N at 0.10 m, 1.8 × 10⁻⁴ N at 0.20 m and 8.0 × 10⁻⁵ N at 0.30 m.'),
('9694f117-ee2b-55b5-abae-0194af03ddef', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 43, 43, 'In an electrostatic precipitator, a smoke particle of mass 2.0 × 10⁻¹³ kg carries a charge of 8.0 × 10⁻¹⁷ C. It is in a field of 5.0 × 10⁵ N C⁻¹ and starts from rest, 0.10 m from a collecting plate. (a) Calculate the electric force on the particle. (b) Calculate its acceleration. (c) Ignoring gravity and air resistance, calculate the time taken to reach the plate, in ms. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '31.62 ms', 'ms', false, NULL, false, NULL, '(a) F = EQ = 5.0 × 10⁵ × 8.0 × 10⁻¹⁷ = 4.0 × 10⁻¹¹ N. (b) a = 4.0 × 10⁻¹¹ ÷ 2.0 × 10⁻¹³ = 200 m s⁻². (c) s = ½at², so t = √(2 × 0.10 ÷ 200) = 0.0316 s. In ms: 0.03162 × 1000 = 31.6. Mark scheme (5 marks). C1: F = EQ. C1: a = F/m. M1: s = ½at² from rest. C1: rearranged for t. A1: t = 31.6 ms.', 5, NULL, NULL),
('5cf5a8fd-07d9-5735-90f0-5875dafbb6e2', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 44, 44, 'In fine weather there is a downward electric field of 120 N C⁻¹ near the ground. A pollen grain of mass 2.0 × 10⁻¹⁴ kg floats without rising or falling, supported only by the electric force. (a) State whether the grain''s charge is positive or negative, and explain. (b) Calculate the charge needed. (c) Calculate the number of electrons this charge represents. Give only the answer to (c). Take g = 9.81 m s⁻² and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '10219', NULL, false, NULL, false, NULL, '(a) Negative: the electric force must be upwards, opposite to the downward field. (b) QE = mg, so Q = 2.0 × 10⁻¹⁴ × 9.81 ÷ 120 = 1.64 × 10⁻¹⁵ C. (c) N = 1.635 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁹ = 1.02 × 10⁴. Mark scheme (6 marks). B1: negative, force opposite to field. M1: QE = mg. C1: Q value. C1: N = Q/e. B1: plausible number of electrons. A1: N = 1.02 × 10⁴.', 6, NULL, NULL),
('91c86d39-cb4b-5c0f-814d-fd6ef137ed73', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 45, 45, '(a) State one similarity and one difference between electric field strength and gravitational field strength. (b) Calculate the electric field strength that would support an electron against its own weight near the Earth''s surface, in units of 10⁻¹¹ N C⁻¹. (c) Comment on why gravitational effects on electrons are usually ignored. Give only the answer to (b). Take mₑ = 9.11 × 10⁻³¹ kg, g = 9.81 m s⁻² and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '5.586', '10⁻¹¹ N C⁻¹', false, NULL, false, NULL, '(a) Both are force per unit of the property (charge or mass) and both are vectors; electric forces can repel, gravitational forces only attract. (b) eE = mₑg, so E = 9.11 × 10⁻³¹ × 9.81 ÷ 1.60 × 10⁻¹⁹ = 5.59 × 10⁻¹¹ N C⁻¹. (c) Even very weak electric fields, such as the 100 N C⁻¹ fair-weather field, give forces about 10¹² times larger. Mark scheme (5 marks). B1: similarity. B1: difference. C1: eE = mg. B1: tiny field needed so gravity negligible. A1: E = 5.59 × 10⁻¹¹ N C⁻¹.', 5, NULL, NULL),
('cf069bcd-d36e-5d4f-9142-a6cfb4f9af8a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 46, 46, 'A test charge of 5.0 nC at point P experiences a force of 3.0 × 10⁻⁴ N directed at 30° above the +x axis. (a) Calculate the field strength at P. (b) Calculate the x-component of the field. (c) State the magnitude and direction of the force on a −2.0 nC charge placed at P instead. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '51962', 'N C⁻¹', false, NULL, false, NULL, '(a) E = F/q = 3.0 × 10⁻⁴ ÷ 5.0 × 10⁻⁹ = 6.0 × 10⁴ N C⁻¹. (b) E_x = 6.0 × 10⁴ × cos 30° = 5.20 × 10⁴ N C⁻¹. (c) F = 6.0 × 10⁴ × 2.0 × 10⁻⁹ = 1.2 × 10⁻⁴ N, directed at 30° below the −x axis, opposite to the field. Mark scheme (5 marks). C1: E = F/q. C1: E_x = E cos 30°. C1: force magnitude on new charge. B1: reversed direction. A1: E_x = 5.20 × 10⁴ N C⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 220" role="img" aria-labelledby="fg7230ac44-t fg7230ac44-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7230ac44-t">Force on a test charge</title><desc id="fg7230ac44-d">The force of 3.0 × 10⁻⁴ N on a 5.0 nC test charge at P, directed at 30° above the +x axis.</desc><line x1="60" y1="170" x2="184.4" y2="98.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="189.9,95 184.7,102.4 180.9,95.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="202" y="88" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 × 10⁻⁴ N</text><line x1="60" y1="170" x2="223.7" y2="170" style="stroke:var(--fig-muted,#6b7280);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,170 221.8,173.8 221.8,166.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="244" y="170" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">+x</text><circle cx="60" cy="170" r="3.4" style="fill:currentColor;stroke:none"/><path d="M110,170 A50,50 0 0,0 103.3,145" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="121.8" y="153.4" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">30°</text></svg>', 'The force of 3.0 × 10⁻⁴ N on a 5.0 nC test charge at P, directed at 30° above the +x axis.'),
('dd97fcd2-0de9-5740-9edf-8eb81ba62f97', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 47, 47, 'In a mass spectrometer, singly charged sodium ions (mass 3.82 × 10⁻²⁶ kg) and potassium ions (mass 6.49 × 10⁻²⁶ kg) start from rest in a uniform field of 2.0 × 10⁴ N C⁻¹. (a) Calculate the force on each ion. (b) Calculate the speed of a sodium ion after 1.0 µs. (c) Calculate the ratio of the speeds (sodium ÷ potassium) at the same time. Give only the answer to (b), in km s⁻¹. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '83.77', 'km s⁻¹', false, NULL, false, NULL, '(a) F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = 3.20 × 10⁻¹⁵ N for both ions. (b) v = at = Ft/m = 3.20 × 10⁻¹⁵ × 1.0 × 10⁻⁶ ÷ 3.82 × 10⁻²⁶ = 8.38 × 10⁴ m s⁻¹. In km s⁻¹: 8.377 × 10⁴ ÷ 1000 = 83.8. (c) Same force and time, so v ∝ 1/m: ratio = 6.49 ÷ 3.82 = 1.70. Mark scheme (6 marks). C1: F = eE. M1: v = (F/m)t from rest. C1: substitution. C1: unit conversion. C1: v ∝ 1/m ratio. A1: v = 83.8 km s⁻¹.', 6, NULL, NULL),
('04ab6ad6-701a-5366-8534-b9a2f78c13a4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 48, 48, 'A field-line diagram is drawn so that the number of lines leaving or ending on a charge is proportional to the charge. Twelve lines leave sphere A, which carries +6.0 nC. Four of these lines end on a nearby sphere B; the rest go off to large distances. No lines leave B. (a) Calculate the charge on B. (b) Explain how you know the sign of B''s charge. (c) State where the field near A is strongest and how the diagram shows this. Give only the magnitude of the answer to (a), in nC.', NULL, 3, 'numeric'::answer_type, '2 nC', 'nC', false, NULL, false, NULL, '(a) Each line represents 6.0 ÷ 12 = 0.50 nC, so B carries 4 × 0.50 = 2.0 nC. (b) Lines end on B, and field lines end on negative charge, so B is −2.0 nC. (c) Close to A''s surface, where the lines are closest together. Mark scheme (5 marks). C1: charge per line. C1: 4 lines on B. B1: lines end on negative charge. B1: strongest where lines densest. A1: Q_B = 2.0 nC.', 5, NULL, NULL),
('1bbc0e0e-dd26-5986-a78c-d8c1a5e63ff1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 49, 49, 'A proton and an α-particle (charge +2e, mass 6.64 × 10⁻²⁷ kg) are released from rest in the same uniform electric field. The proton mass is 1.67 × 10⁻²⁷ kg. (a) Calculate the ratio of the forces (α ÷ proton). (b) Calculate the ratio of their accelerations (α ÷ proton). (c) State the ratio of their kinetic energies after each has moved the same distance, and explain. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.503', NULL, false, NULL, false, NULL, '(a) Force ratio = 2e ÷ e = 2. (b) Acceleration ratio = (2e ÷ 6.64 × 10⁻²⁷) ÷ (e ÷ 1.67 × 10⁻²⁷) = 2 × 1.67 ÷ 6.64 = 0.503. (c) KE gained = work done = F × distance, so the α-particle gains twice the kinetic energy. Mark scheme (5 marks). C1: force ratio 2. M1: a = qE/m. C1: substitution. B1: KE = Fd so ratio 2. A1: ratio = 0.503.', 5, NULL, NULL),
('e5390e33-f856-5fc5-91b4-189158f65418', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', '7ef293ce-52e7-56ce-9b56-5d610fce5bd5', 'a-level', '21.2', '9702 coursebook 21.2 · Electric fields and field lines', 50, 50, 'To measure the field at a fixed point, a student places different small test charges there and measures the force: q/nC = 1.0, 2.0, 3.0, 4.0 and F/µN = 24, 49, 71, 97. (a) Describe the graph of F against q. (b) Calculate the gradient of the graph from the first and last readings. (c) Use the gradient to find the field strength. (d) Explain why the student should not use a much larger test charge. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '24333', 'N C⁻¹', false, NULL, false, NULL, '(a) A straight line through the origin, so F ∝ q. (b) Gradient = (97 − 24) × 10⁻⁶ ÷ ((4.0 − 1.0) × 10⁻⁹) = 2.43 × 10⁴ N C⁻¹. (c) F = Eq, so E = gradient = 2.43 × 10⁴ N C⁻¹. (d) A large test charge would exert forces on the source charges and change the field it was meant to measure. Mark scheme (6 marks). B1: straight line through origin. C1: gradient with units converted. M1: E = gradient. B1: large q disturbs field. C1: substitution. A1: E = 2.43 × 10⁴ N C⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fg47b45b04-t fg47b45b04-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg47b45b04-t">Force against test charge</title><desc id="fg47b45b04-d">Table and graph of force against test charge at a fixed point: q = 1.0, 2.0, 3.0, 4.0 nC give F = 24, 49, 71, 97 µN, close to a straight line through the origin.</desc><g transform="translate(0,0)"><rect x="133.4" y="8" width="133.1" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="133.4" y="8" width="133.1" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,7