('34be7974-6231-56f1-9b17-9557c5cad613', 'f9eba46c-77ac-5fd7-a634-7866f31df850', 'Inside the conductor', 'C', false, 2),
('9d538906-b1c0-588e-9688-a74c8e284f39', 'f9eba46c-77ac-5fd7-a634-7866f31df850', 'Near the most sharply curved, pointed end', 'D', true, 3),
('93db0082-91fd-57fd-9ab7-8fd0c784f5c5', '95dc985a-494f-549c-83b6-a895603420d6', 'The field lines point away from the sphere and the test charge is pushed away', 'A', false, 0),
('dbc400b5-92c6-5baa-a1a8-7b1365c6c3cd', '95dc985a-494f-549c-83b6-a895603420d6', 'The field lines point towards the sphere and the test charge is pulled towards it', 'B', true, 1),
('a8a80986-7f71-5589-a0d5-482282ac9172', '95dc985a-494f-549c-83b6-a895603420d6', 'The field lines point towards the sphere but the test charge is pushed away', 'C', false, 2),
('84aa0680-d3f7-54b7-bd27-205eaa1a7bd8', '95dc985a-494f-549c-83b6-a895603420d6', 'There is no field outside a negatively charged sphere', 'D', false, 3),
('c095e7a1-5614-5ff8-8453-68cc37ad44b8', '84f3343b-0e98-5d7d-883c-56878b30d9ea', 'So that it does not fall under gravity', 'A', false, 0),
('2b03308b-585c-5d1c-b7de-435d5a23499a', '84f3343b-0e98-5d7d-883c-56878b30d9ea', 'So that the force on it is large', 'B', false, 1),
('99125647-c763-51fd-b592-e2aa3ff08d0a', '84f3343b-0e98-5d7d-883c-56878b30d9ea', 'So that it does not disturb the charges that produce the field being measured', 'C', true, 2),
('36d615fe-e46f-5f0e-80af-d44ad8ccddb6', '84f3343b-0e98-5d7d-883c-56878b30d9ea', 'Because large charges have no field', 'D', false, 3),
('d864cebe-ea66-51e6-b14a-00b00c032aaa', '59697131-8779-5915-98e6-3c181922490b', 'Along the line joining them, towards the negative charge', 'A', true, 0),
('6fc5362e-0ae3-511a-acda-cc7f0ae4c721', '59697131-8779-5915-98e6-3c181922490b', 'Along the line joining them, towards the positive charge', 'B', false, 1),
('069dd86a-d9a9-5341-8d57-972763eb7801', '59697131-8779-5915-98e6-3c181922490b', 'Perpendicular to the line joining them', 'C', false, 2),
('caea9969-301c-55ba-8e97-531a53c97e44', '59697131-8779-5915-98e6-3c181922490b', 'There is no field at the midpoint', 'D', false, 3),
('e2313716-c1f8-5051-938a-5b8e64aa032b', '069b71af-04b8-524e-8b61-d9b31a838ac3', 'It is positive', 'A', false, 0),
('a10081cc-8763-501b-b096-60a50ea85130', '069b71af-04b8-524e-8b61-d9b31a838ac3', 'It is zero', 'B', false, 1),
('9bd75ccd-5e8e-5e69-b408-f9d8aaa746a4', '069b71af-04b8-524e-8b61-d9b31a838ac3', 'It changes sign every second', 'C', false, 2),
('999aba92-f29c-5476-90f7-f2c3ca268f9b', '069b71af-04b8-524e-8b61-d9b31a838ac3', 'It is negative', 'D', true, 3),
('bdcca918-5000-5786-ba12-3fb1c035c694', '09f14b74-d01d-5d10-b676-07bdd9b2511b', 'Radial lines spreading out from the centre of the plate', 'A', false, 0),
('440f3011-f6db-5211-b8da-4639df38e05c', '09f14b74-d01d-5d10-b676-07bdd9b2511b', 'Parallel lines perpendicular to the plate, pointing away from it, equally spaced', 'B', true, 1),
('f7d1fec7-f41b-5ea2-be84-af6f557b3a68', '09f14b74-d01d-5d10-b676-07bdd9b2511b', 'Lines parallel to the plate surface', 'C', false, 2),
('53122fb9-3f4f-59b7-bc60-426cc8f901b1', '09f14b74-d01d-5d10-b676-07bdd9b2511b', 'Concentric circles around the plate', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('a86534bd-18f1-5c63-a09e-3b36d08a1eec', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 9, 9, 'The two parallel plates in an ink-jet printer head are 0.50 mm apart and have 150 V between them. Calculate the electric field strength between the plates.', NULL, 1, 'numeric'::answer_type, '3e5', 'V m⁻¹', false, NULL, false, NULL, 'E = V/d = 150 ÷ 0.50 × 10⁻³ = 3.0 × 10⁵ V m⁻¹. Mark scheme (2 marks). C1: E = V/d with d in m. A1: E = 3.0 × 10⁵ V m⁻¹.', 2, NULL, NULL),
('fc6fec20-4a43-5557-824d-13c0585e86f1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 10, 10, 'How are the field lines drawn in the central region between two parallel plates connected to a supply?', NULL, 1, 'multiple_choice'::answer_type, 'Parallel, equally spaced, from the positive plate to the negative plate', NULL, false, NULL, false, NULL, 'A uniform field is shown by parallel, equally spaced lines pointing from + to −. Mark scheme (1 mark). B1: C (Parallel, equally spaced, from the positive plate to the negative plate).', 1, NULL, NULL),
('14ac0274-f1c8-59d3-a363-53eac5886f12', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 11, 11, 'The separation of two parallel plates is doubled while the p.d. between them is kept constant. What happens to the field strength between them?', NULL, 1, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'E = V/d: with V fixed, doubling d halves E. Mark scheme (1 mark). B1: A (It halves).', 1, NULL, NULL),
('eebbe997-3336-507b-9a97-2380c10d36ba', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 12, 12, 'Dry air breaks down and conducts when the field strength reaches 3.0 × 10⁶ V m⁻¹. Calculate the largest p.d. that can be applied across an air gap of 2.0 mm without sparking.', NULL, 1, 'numeric'::answer_type, '6000', 'V', false, NULL, false, NULL, 'V = Ed = 3.0 × 10⁶ × 2.0 × 10⁻³ = 6000 V. Mark scheme (2 marks). C1: V = Ed. A1: V = 6000 V.', 2, NULL, NULL),
('10b5cb85-133b-5c53-969a-1c5f3cdf3e64', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 13, 13, 'Which unit is equivalent to V m⁻¹?', NULL, 1, 'multiple_choice'::answer_type, 'N C⁻¹', NULL, false, NULL, false, NULL, '1 V = 1 J C⁻¹, so V m⁻¹ = J C⁻¹ m⁻¹ = N C⁻¹. Mark scheme (1 mark). B1: D (N C⁻¹).', 1, NULL, NULL),
('426c42bc-f425-58b0-a4d6-ac533b64805f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 14, 14, 'An electron is accelerated from rest through a p.d. of 2000 V. Calculate the kinetic energy it gains, in units of 10⁻¹⁶ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.2', '10⁻¹⁶ J', false, NULL, false, NULL, 'E_k = eV = 1.60 × 10⁻¹⁹ × 2000 = 3.20 × 10⁻¹⁶ J. Mark scheme (2 marks). C1: W = QV. A1: E_k = 3.2 × 10⁻¹⁶ J.', 2, NULL, NULL),
('08902a32-2502-5c1a-a349-7430b84dab64', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 15, 15, 'An electron is released from rest close to the negative plate of a pair of parallel plates in a vacuum. How does it move?', NULL, 1, 'multiple_choice'::answer_type, 'It accelerates uniformly towards the positive plate', NULL, false, NULL, false, NULL, 'The uniform field gives a constant force and so a constant acceleration, towards the positive plate for a negative charge. Mark scheme (1 mark). B1: B (It accelerates uniformly towards the positive plate).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg2c07b318-t fg2c07b318-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2c07b318-t">Electron near the negative plate</title><desc id="fg2c07b318-d">Parallel plates in a vacuum with a uniform field from the positive (top) plate to the negative (bottom) plate; an electron is released from rest just above the negative plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><circle cx="200" cy="158" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="158.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="212" y="146" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electron</text></svg>', 'Parallel plates in a vacuum with a uniform field from the positive (top) plate to the negative (bottom) plate; an electron is released from rest just above the negative plate.'),
('4cf7ead4-8760-5f45-bd35-425ff00569e2', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 16, 16, 'Before a thunderstorm, the field between the base of a cloud and the ground 800 m below is roughly uniform at 1.5 × 10⁴ V m⁻¹. Calculate the p.d. between the cloud base and the ground.', NULL, 1, 'numeric'::answer_type, '1.2e7', 'V', false, NULL, false, NULL, 'V = Ed = 1.5 × 10⁴ × 800 = 1.2 × 10⁷ V. Mark scheme (2 marks). C1: V = Ed. A1: V = 1.2 × 10⁷ V.', 2, NULL, NULL),
('e8866364-b307-5aea-86e3-60916aa4660d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 17, 17, 'What happens to the electric field near the edges of a pair of parallel plates?', NULL, 1, 'multiple_choice'::answer_type, 'The field lines curve outwards and the field is no longer uniform', NULL, false, NULL, false, NULL, 'Edge effects make the field non-uniform; only the central region is uniform. Mark scheme (1 mark). B1: C (The field lines curve outwards and the field is no longer uniform).', 1, NULL, NULL),
('311c34ec-05ca-504f-b43a-1407033328d0', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 18, 18, 'A proton travels from the positive plate to the negative plate of a pair with a p.d. of 500 V between them. Calculate the kinetic energy it gains, in units of 10⁻¹⁷ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8', '10⁻¹⁷ J', false, NULL, false, NULL, 'E_k = eV = 1.60 × 10⁻¹⁹ × 500 = 8.00 × 10⁻¹⁷ J. Mark scheme (2 marks). C1: W = QV. A1: E_k = 8.0 × 10⁻¹⁷ J.', 2, NULL, NULL),
('e1acd7f4-7d6e-5df9-8b57-00c18d0c7734', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 19, 19, 'The p.d. between two parallel plates is doubled at constant separation. What happens to the force on a charged particle between them?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'F = QE = QV/d, so at fixed d the force is proportional to V. Mark scheme (1 mark). B1: A (It doubles).', 1, NULL, NULL),
('61cb17e1-0dcc-5fc9-bae8-0ed7dff3f225', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 20, 20, 'A cell membrane is 7.0 nm thick and has a p.d. of 70 mV across it. Treating it as a uniform field, calculate the field strength in the membrane.', NULL, 1, 'numeric'::answer_type, '1e7', 'V m⁻¹', false, NULL, false, NULL, 'E = V/d = 70 × 10⁻³ ÷ 7.0 × 10⁻⁹ = 1.0 × 10⁷ V m⁻¹. Mark scheme (2 marks). C1: E = V/d with units converted. A1: E = 1.0 × 10⁷ V m⁻¹.', 2, NULL, NULL),
('6917bc60-4ea6-5370-b917-4a9e12e03542', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 21, 21, 'Which describes the graph of electric potential against distance across the gap between two parallel plates?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line', NULL, false, NULL, false, NULL, 'In a uniform field the potential changes by the same amount for each metre: V varies linearly with distance. Mark scheme (1 mark). B1: D (A straight line).', 1, NULL, NULL),
('2d216725-af8d-5865-9fe2-e3a90b6d75e9', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 22, 22, 'Parallel plates 0.030 m apart have a p.d. of 600 V. Calculate the force on a charge of 4.0 µC between them.', NULL, 1, 'numeric'::answer_type, '0.08', 'N', false, NULL, false, NULL, 'E = 600 ÷ 0.030 = 2.0 × 10⁴ V m⁻¹. F = EQ = 2.0 × 10⁴ × 4.0 × 10⁻⁶ = 0.080 N. Mark scheme (2 marks). C1: E = V/d then F = EQ. A1: F = 0.080 N.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fga99d8a07-t fga99d8a07-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga99d8a07-t">Charge between plates</title><desc id="fga99d8a07-d">Parallel plates 0.030 m apart with a p.d. of 600 V; a charge of 4.0 µC sits in the uniform field between them.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polygon points="332,50 335,56.3 329,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="332" y1="54.9" x2="332" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="332,170 329,163.7 335,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.030 m</text><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">600 V</text><circle cx="200" cy="110" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="110.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="212" y="98" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 µC</text></svg>', 'Parallel plates 0.030 m apart with a p.d. of 600 V; a charge of 4.0 µC sits in the uniform field between them.'),
('3deae430-4653-5643-9dd6-63d36e7882f0', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 23, 23, 'A small charged particle is moved to different positions in the central region between two parallel plates. How does the electric force on it change?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same everywhere in the uniform field', NULL, false, NULL, false, NULL, 'In a uniform field E is the same at every point, so F = QE is constant. Mark scheme (1 mark). B1: B (It stays the same everywhere in the uniform field).', 1, NULL, NULL),
('71cf145a-4cdb-5a7a-b548-9030f405d020', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 24, 24, 'An electron is accelerated from rest through a p.d. of 500 V. Calculate its final speed. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '1.325e7', 'm s⁻¹', false, NULL, false, NULL, '½mv² = eV, so v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 500 ÷ 9.11 × 10⁻³¹) = 1.33 × 10⁷ m s⁻¹. Mark scheme (3 marks). M1: ½mv² = eV. C1: substitution. A1: v = 1.33 × 10⁷ m s⁻¹.', 3, NULL, NULL),
('129a60fc-a981-503d-9994-e398c21a57a3', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 25, 25, 'Two parallel plates are 2.0 cm apart with a p.d. of 400 V between them. Calculate the acceleration of an electron between the plates. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '3.513e15', 'm s⁻²', false, NULL, false, NULL, 'E = V/d = 400 ÷ 0.020 = 2.0 × 10⁴ V m⁻¹. F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = 3.20 × 10⁻¹⁵ N. a = F/m = 3.20 × 10⁻¹⁵ ÷ 9.11 × 10⁻³¹ = 3.51 × 10¹⁵ m s⁻². Mark scheme (4 marks). C1: E = V/d. C1: F = eE. C1: a = F/m. A1: a = 3.51 × 10¹⁵ m s⁻².', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg3fca5af2-t fg3fca5af2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3fca5af2-t">Electron between plates</title><desc id="fg3fca5af2-d">Parallel plates 2.0 cm apart with a p.d. of 400 V; an electron is in the uniform field between them.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polygon points="332,50 335,56.3 329,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="332" y1="54.9" x2="332" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="332,170 329,163.7 335,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.0 cm</text><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">400 V</text><circle cx="200" cy="110" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="110.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="212" y="98" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electron</text></svg>', 'Parallel plates 2.0 cm apart with a p.d. of 400 V; an electron is in the uniform field between them.'),
('a4237f57-96e7-5e08-bc12-ec652ef501e4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 26, 26, 'Both the p.d. between two parallel plates and their separation are doubled. What happens to the field strength?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'E = V/d: doubling both leaves the ratio unchanged. Mark scheme (3 marks). C1: E = V/d. C1: ratio unchanged. A1: C (It stays the same).', 3, NULL, NULL),
('f3f2d4a7-f677-5f45-ad38-4b5b2e7a270d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 27, 27, 'In the first stage of a particle accelerator, protons starting at rest gain energy from a 1.0 kV potential difference. What speed do they reach? Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '4.377e5', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 1000 ÷ 1.67 × 10⁻²⁷) = 4.38 × 10⁵ m s⁻¹. Mark scheme (3 marks). M1: ½mv² = eV. C1: substitution. A1: v = 4.38 × 10⁵ m s⁻¹.', 3, NULL, NULL),
('b83f0626-3242-54fb-b6e8-19a262b1592b', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 28, 28, 'An electron starts from rest at the negative plate of a pair of parallel plates 1.0 cm apart. The field strength is 5.0 × 10³ V m⁻¹. Calculate the time it takes to reach the positive plate, in ns. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '4.772 ns', 'ns', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 5.0 × 10³ ÷ 9.11 × 10⁻³¹ = 8.78 × 10¹⁴ m s⁻². t = √(2d/a) = √(2 × 0.010 ÷ 8.782 × 10¹⁴) = 4.77 × 10⁻⁹ s. In ns: 4.772 × 10⁻⁹ × 10⁹ = 4.77. Mark scheme (3 marks). C1: a = eE/m. C1: s = ½at². A1: t = 4.77 ns.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fgaf7368ee-t fgaf7368ee-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaf7368ee-t">Electron crossing the gap</title><desc id="fgaf7368ee-d">Parallel plates 1.0 cm apart with a uniform field of 5.0 × 10³ V m⁻¹; an electron starts from rest at the negative (bottom) plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polygon points="332,50 335,56.3 329,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="332" y1="54.9" x2="332" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="332,170 329,163.7 335,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">1.0 cm</text><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 5.0 × 10³ V m⁻¹</text><circle cx="200" cy="160.4" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="160.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="212" y="148.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electron</text></svg>', 'Parallel plates 1.0 cm apart with a uniform field of 5.0 × 10³ V m⁻¹; an electron starts from rest at the negative (bottom) plate.'),
('35e9c7f8-65cd-589e-8e1f-8b63233b59fe', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 29, 29, 'An electron enters the uniform field between two horizontal plates, moving horizontally. The upper plate is positive. Which statement about its motion is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Its horizontal velocity stays constant while it accelerates upwards, so it follows a parabola', NULL, false, NULL, false, NULL, 'The force is vertical and constant, like gravity on a projectile, but towards the positive plate. Mark scheme (3 marks). C1: constant force perpendicular to initial velocity. C1: parabolic path towards + plate. A1: A (Its horizontal velocity stays constant while it accelerates upwards, so it follows a parabola).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fgc44c18a4-t fgc44c18a4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc44c18a4-t">Electron entering the field</title><desc id="fgc44c18a4-d">Two horizontal plates, upper plate positive, with a uniform field between them; an electron enters midway, moving horizontally.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">electron</text></svg>', 'Two horizontal plates, upper plate positive, with a uniform field between them; an electron enters midway, moving horizontally.'),
('dc7c4a94-6d25-57bf-af90-86f8903f5a21', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 30, 30, 'In a petrol engine, the spark plug gap is 0.80 mm. In the compressed fuel–air mixture, sparking needs a field strength of about 1.0 × 10⁷ V m⁻¹. Calculate the minimum p.d. needed across the gap.', NULL, 2, 'numeric'::answer_type, '8000', 'V', false, NULL, false, NULL, 'V = Ed = 1.0 × 10⁷ × 0.80 × 10⁻³ = 8000 V. Mark scheme (3 marks). C1: V = Ed. C1: gap in m. A1: V = 8000 V.', 3, NULL, NULL),
('5a4be24b-4471-561e-bbda-ea6057e91619', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 31, 31, 'The electron gun of an X-ray tube accelerates electrons through 5.0 kV, and the beam current is 2.0 mA. Calculate the energy delivered to the target by the beam each second.', NULL, 2, 'numeric'::answer_type, '10', 'W', false, NULL, false, NULL, 'Each coulomb gains 5.0 × 10³ J, and 2.0 × 10⁻³ C arrives each second: P = IV = 2.0 × 10⁻³ × 5.0 × 10³ = 10 W. Mark scheme (3 marks). C1: energy per coulomb = V. C1: P = IV. A1: P = 10 W.', 3, NULL, NULL),
('e7de5518-527c-5406-9e28-d0349be1e115', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 32, 32, 'Calculate the field strength needed to give an electron an acceleration of 1.0 × 10¹⁵ m s⁻². Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '5694', 'V m⁻¹', false, NULL, false, NULL, 'eE = ma, so E = ma/e = 9.11 × 10⁻³¹ × 1.0 × 10¹⁵ ÷ 1.60 × 10⁻¹⁹ = 5690 V m⁻¹. Mark scheme (3 marks). M1: eE = ma. C1: substitution. A1: E = 5690 V m⁻¹.', 3, NULL, NULL),
('f5d810cd-63b3-5ba5-814a-4f85a7471bd7', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 33, 33, 'Two parallel plates stay connected to a constant-voltage supply. The plates are moved closer together until the separation is halved. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'p.d. unchanged; field strength doubles', NULL, false, NULL, false, NULL, 'The supply fixes V, so E = V/d doubles when d halves. Mark scheme (3 marks). C1: V fixed by supply. C1: E = V/d. A1: D (p.d. unchanged; field strength doubles).', 3, NULL, NULL),
('86d69b47-5177-531b-baa1-0eaff5f6050a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 34, 34, 'Two parallel plates are 10 cm apart. One is at 0 V and the other at +200 V. Calculate the potential at a point 3.0 cm from the 0 V plate.', NULL, 2, 'numeric'::answer_type, '60', 'V', false, NULL, false, NULL, 'The potential rises uniformly: V = 200 × 3.0 ÷ 10 = 60 V. Mark scheme (3 marks). C1: uniform potential gradient. C1: proportion of the distance. A1: V = 60 V.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg2d750fca-t fg2d750fca-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2d750fca-t">Potential between plates</title><desc id="fg2d750fca-d">Parallel plates 10 cm apart: the top plate is at +200 V and the bottom plate at 0 V. Point P is 3.0 cm from the 0 V plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+200 V</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">0 V</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polygon points="332,50 335,56.3 329,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="332" y1="54.9" x2="332" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="332,170 329,163.7 335,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">10 cm</text><circle cx="200" cy="134" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="134.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700"></text><text x="212" y="122" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">P (3.0 cm from 0 V)</text></svg>', 'Parallel plates 10 cm apart: the top plate is at +200 V and the bottom plate at 0 V. Point P is 3.0 cm from the 0 V plate.'),
('98d8aebc-81f9-5702-af6d-ed9ade957ca9', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 35, 35, 'An α-particle (charge +2e) is accelerated from rest through a p.d. of 2.0 kV. Calculate the kinetic energy it gains, in keV.', NULL, 2, 'numeric'::answer_type, '4', 'keV', false, NULL, false, NULL, 'E_k = QV = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10³ = 6.4 × 10⁻¹⁶ J. In keV: 6.4 × 10⁻¹⁶ ÷ 1.6 × 10⁻¹⁶ = 4.0. Mark scheme (3 marks). C1: Q = 2e. C1: W = QV. A1: E_k = 4.0 keV. Common mistake: Using Q = e gives 2.0 keV: the α-particle carries two units of charge.', 3, NULL, NULL),
('aef44e2f-7471-534c-81c2-4875d465bc37', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 36, 36, 'Why can the weight of an electron be ignored when it moves between charged parallel plates?', NULL, 2, 'multiple_choice'::answer_type, 'The electric force (about 10⁻¹⁵ N in typical fields) is many orders of magnitude larger than its weight (about 10⁻²⁹ N)', NULL, false, NULL, false, NULL, 'mₑg ≈ 9 × 10⁻³⁰ N, which is negligible compared with eE. Mark scheme (3 marks). C1: compares magnitudes. C1: weight negligible. A1: B (The electric force (about 10⁻¹⁵ N in typical fields) is many orders of magnitude larger than its weight (about 10⁻²⁹ N)).', 3, NULL, NULL),
('a54d3be5-928c-5126-89d2-25384ddaf8c4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 37, 37, 'Two horizontal plates produce a uniform downward field of 5.0 × 10⁴ V m⁻¹. A charge of +2.0 µC is moved from a point 1.0 cm above the lower plate to a point 4.0 cm above it and 3.0 cm to one side. Calculate the work done against the electric force.', NULL, 2, 'numeric'::answer_type, '0.003', 'J', false, NULL, false, NULL, 'Only the displacement along the field matters. The charge rises 4.0 − 1.0 = 3.0 cm against the field: W = QEΔx = 2.0 × 10⁻⁶ × 5.0 × 10⁴ × 0.030 = 3.0 × 10⁻³ J. Mark scheme (4 marks). M1: only component along E counts. C1: Δx = 3.0 cm. C1: W = QEΔx. A1: W = 0.0030 J.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg32008fdf-t fg32008fdf-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg32008fdf-t">Moving a charge between plates</title><desc id="fg32008fdf-d">Horizontal plates with a uniform downward field of 5.0 × 10⁴ V m⁻¹. A +2.0 µC charge is moved from 1.0 cm above the lower plate to 4.0 cm above it and 3.0 cm to one side.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 5.0 × 10⁴ V m⁻¹ (down)</text><circle cx="156" cy="146" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="156" y="146.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="168" y="134" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.0 cm up</text><circle cx="222" cy="74" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="222" y="74.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="234" y="62" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 cm up</text></svg>', 'Horizontal plates with a uniform downward field of 5.0 × 10⁴ V m⁻¹. A +2.0 µC charge is moved from 1.0 cm above the lower plate to 4.0 cm above it and 3.0 cm to one side.'),
('b5799a3f-660d-5e95-a229-46cfb879a606', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 38, 38, 'Which describes the graph of electric field strength against position across the gap between two parallel plates (away from the edges)?', NULL, 2, 'multiple_choice'::answer_type, 'A horizontal line', NULL, false, NULL, false, NULL, 'The field is uniform, so E has the same value at every point. Mark scheme (3 marks). C1: uniform field. C1: constant E. A1: C (A horizontal line).', 3, NULL, NULL),
('5c563483-dfef-503e-9f87-2b461dc487b2', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 39, 39, 'An electron moving at 3.0 × 10⁶ m s⁻¹ heads straight towards a negatively charged plate. Calculate the p.d. that would just bring it to rest. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '25.62', 'V', false, NULL, false, NULL, 'eV = ½mv², so V = 0.5 × 9.11 × 10⁻³¹ × (3.0 × 10⁶)² ÷ 1.60 × 10⁻¹⁹ = 25.6 V. Mark scheme (3 marks). M1: eV = ½mv². C1: substitution. A1: V = 25.6 V.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fgea87ba81-t fgea87ba81-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgea87ba81-t">Electron approaching a negative plate</title><desc id="fgea87ba81-d">An electron moving at 3.0 × 10⁶ m s⁻¹ heads straight towards the negatively charged (bottom) plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><circle cx="200" cy="80" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="200" y="80.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="212" y="68" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 × 10⁶ m s⁻¹, moving down</text></svg>', 'An electron moving at 3.0 × 10⁶ m s⁻¹ heads straight towards the negatively charged (bottom) plate.'),
('a956d5af-73d5-5792-a11e-356a9513a091', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 40, 40, 'An electron starts at rest on the negative plate and reaches the positive plate with a speed of 8.0 × 10⁶ m s⁻¹. Calculate the p.d. between the plates. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '182.2', 'V', false, NULL, false, NULL, 'V = ½mv²/e = 0.5 × 9.11 × 10⁻³¹ × (8.0 × 10⁶)² ÷ 1.60 × 10⁻¹⁹ = 182 V. Mark scheme (3 marks). M1: eV = ½mv². C1: substitution. A1: V = 182 V.', 3, NULL, NULL),
('eb09ad70-d8c9-5ad4-a0fa-930d93c9329c', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'ea6e0ded-f55f-54ce-803b-1143224c470a', 'a-level', '21.3', '9702 coursebook 21.3 · Uniform electric fields', 41, 41, 'An electron moving horizontally at 2.0 × 10⁷ m s⁻¹ enters the uniform field between two horizontal plates 5.0 cm long. The field strength between the plates is 1.0 × 10⁴ V m⁻¹. (a) Calculate the time the electron spends between the plates. (b) Calculate its vertical acceleration. (c) Calculate its vertical deflection as it leaves the plates, in mm. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '5.488 mm', 'mm', false, NULL, false, NULL, '(a) t = 0.050 ÷ 2.0 × 10⁷ = 2.5 × 10⁻⁹ s. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 9.11 × 10⁻³¹ = 1.76 × 10¹⁵ m s⁻². (c) y = ½at² = 0.5 × 1.756 × 10¹⁵ × (2.5 × 10⁻⁹)² = 0.00549 m. In mm: 0.005488 × 1000 = 5.49. Mark scheme (6 marks). C1: horizontal velocity constant, t = L/v. C1: a = eE/m. M1: y = ½at². C1: substitution. C1: conversion to mm. A1: y = 5.49 mm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg62580553-t fg62580553-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg62580553-t">Electron deflected between plates</title><desc id="fg62580553-d">An electron moving horizontally at 2.0 × 10⁷ m s⁻¹ enters the uniform field (1.0 × 10⁴ V m⁻¹) between horizontal plates 5.0 cm long and is deflected towards the positive plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" te