('6eee4353-5eda-52f3-a17c-d26973fa8081', 'e1acd7f4-7d6e-5df9-8b57-00c18d0c7734', 'It quadruples', 'D', false, 3),
('3bdeb390-2df9-5785-89b4-22994d527741', '6917bc60-4ea6-5370-b917-4a9e12e03542', 'A curve that gets steeper', 'A', false, 0),
('39c53205-b762-575e-848e-25daee6e25ff', '6917bc60-4ea6-5370-b917-4a9e12e03542', 'A horizontal line', 'B', false, 1),
('6b4fe0b4-6552-59ba-817d-d5bb87018806', '6917bc60-4ea6-5370-b917-4a9e12e03542', 'A curve that levels off', 'C', false, 2),
('8efc56b7-21bd-52ab-9aeb-55537a880e49', '6917bc60-4ea6-5370-b917-4a9e12e03542', 'A straight line', 'D', true, 3),
('1e8479f9-46ab-570e-ad81-294c0f14934f', '3deae430-4653-5643-9dd6-63d36e7882f0', 'It is largest near the positive plate', 'A', false, 0),
('128201f0-68d6-5016-94b8-9333f1d09686', '3deae430-4653-5643-9dd6-63d36e7882f0', 'It stays the same everywhere in the uniform field', 'B', true, 1),
('0b52ff69-fc03-5bdf-960d-ebd55fe08f85', '3deae430-4653-5643-9dd6-63d36e7882f0', 'It is largest near the negative plate', 'C', false, 2),
('530994d9-83ab-57f6-b02d-86309ec215a6', '3deae430-4653-5643-9dd6-63d36e7882f0', 'It is largest midway between the plates', 'D', false, 3),
('089c010a-dd9a-5ffe-a51d-9e2cd8a15618', 'a4237f57-96e7-5e08-bc12-ec652ef501e4', 'It doubles', 'A', false, 0),
('49e44c86-55f8-5f38-9676-f6f07f4440a0', 'a4237f57-96e7-5e08-bc12-ec652ef501e4', 'It quadruples', 'B', false, 1),
('0450bd6b-0e42-5801-ae94-67ed0c733598', 'a4237f57-96e7-5e08-bc12-ec652ef501e4', 'It stays the same', 'C', true, 2),
('eff05a30-db45-5611-9041-a90e2ad061e2', 'a4237f57-96e7-5e08-bc12-ec652ef501e4', 'It halves', 'D', false, 3),
('6806d735-b372-5518-a64e-10a4c64449b3', '35e9c7f8-65cd-589e-8e1f-8b63233b59fe', 'Its horizontal velocity stays constant while it accelerates upwards, so it follows a parabola', 'A', true, 0),
('9c6ff537-0db9-5114-8067-d879d5dbd55f', '35e9c7f8-65cd-589e-8e1f-8b63233b59fe', 'It moves in a circle', 'B', false, 1),
('1f3badca-b339-5443-8530-8fea64bf984b', '35e9c7f8-65cd-589e-8e1f-8b63233b59fe', 'It slows down horizontally and stops', 'C', false, 2),
('b3987a86-87fe-5cbc-a3f8-7d695777e93d', '35e9c7f8-65cd-589e-8e1f-8b63233b59fe', 'It moves in a straight line towards the lower plate', 'D', false, 3),
('dd4331c8-0377-578f-b854-711543ad60da', 'f5d810cd-63b3-5ba5-814a-4f85a7471bd7', 'p.d. halves; field strength unchanged', 'A', false, 0),
('611847af-c4ed-5c70-9d7d-3df6d748c096', 'f5d810cd-63b3-5ba5-814a-4f85a7471bd7', 'p.d. doubles; field strength doubles', 'B', false, 1),
('b117a0fc-956d-5806-a9bb-122bdd3527eb', 'f5d810cd-63b3-5ba5-814a-4f85a7471bd7', 'p.d. unchanged; field strength halves', 'C', false, 2),
('92e2febb-b22d-5a6f-a6bf-f7138b3fb96b', 'f5d810cd-63b3-5ba5-814a-4f85a7471bd7', 'p.d. unchanged; field strength doubles', 'D', true, 3),
('1a6795c2-d9df-5282-9e54-beb72cf9408c', 'aef44e2f-7471-534c-81c2-4875d465bc37', 'Electrons have no mass', 'A', false, 0),
('7bffdacf-4f28-5050-b7c7-00ef21c0374b', 'aef44e2f-7471-534c-81c2-4875d465bc37', 'The electric force (about 10⁻¹⁵ N in typical fields) is many orders of magnitude larger than its weight (about 10⁻²⁹ N)', 'B', true, 1),
('b4aacac5-67e5-55c1-93ee-9cb29c79969f', 'aef44e2f-7471-534c-81c2-4875d465bc37', 'Gravity does not act in a vacuum', 'C', false, 2),
('33fa9eb5-160c-5acc-9a53-3dd73a187201', 'aef44e2f-7471-534c-81c2-4875d465bc37', 'The electric force cancels the weight exactly', 'D', false, 3),
('35efeb73-9806-559e-9147-01243bc139b7', 'b5799a3f-660d-5e95-a229-46cfb879a606', 'A straight line through the origin', 'A', false, 0),
('8a9a4e52-81bc-5f8f-ac68-b187162c8aef', 'b5799a3f-660d-5e95-a229-46cfb879a606', 'A curve that falls with distance', 'B', false, 1),
('e1dfc818-b0b2-5cbe-bc02-447f71301c07', 'b5799a3f-660d-5e95-a229-46cfb879a606', 'A horizontal line', 'C', true, 2),
('92262d54-443e-5621-b51a-08203f4764a9', 'b5799a3f-660d-5e95-a229-46cfb879a606', 'A curve that rises with distance', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('7fd8cda9-0ab0-5a50-9599-046d5a08b5f6', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 7, 7, 'A charged dust particle carrying −2.0 nC is in an electric field of strength 3.0 × 10⁴ N C⁻¹. Calculate the magnitude of the force on it.', NULL, 1, 'numeric'::answer_type, '6e-5', 'N', false, NULL, false, NULL, 'F = EQ = 3.0 × 10⁴ × 2.0 × 10⁻⁹ = 6.0 × 10⁻⁵ N. Mark scheme (2 marks). C1: F = EQ with Q in C. A1: F = 6.0 × 10⁻⁵ N.', 2, NULL, NULL),
('2cfe13b5-60cb-5d15-933c-72a32d5abbbd', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 8, 8, 'In which direction is the electric force on a positive charge in an electric field?', NULL, 1, 'multiple_choice'::answer_type, 'In the direction of the field', NULL, false, NULL, false, NULL, 'The field direction is defined as the direction of the force on a positive charge. Mark scheme (1 mark). B1: C (In the direction of the field).', 1, NULL, NULL),
('a8b36fb6-d79f-56ab-9ba4-49ee3044b981', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 9, 9, 'An electron and a proton are placed at the same point in an electric field. How do the forces on them compare?', NULL, 1, 'multiple_choice'::answer_type, 'Equal in size and opposite in direction', NULL, false, NULL, false, NULL, 'F = QE and the charges are equal in size but opposite in sign. Mark scheme (1 mark). B1: A (Equal in size and opposite in direction).', 1, NULL, NULL),
('5d5a8b72-d9cc-5fde-8b34-9766c452bb84', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 10, 10, 'An α-particle has a charge of +2e. Calculate the force on it in an electric field of 5.0 × 10⁴ N C⁻¹, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.6', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = 2eE = 2 × 1.60 × 10⁻¹⁹ × 5.0 × 10⁴ = 1.60 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: Q = 2e and F = QE. A1: F = 1.6 × 10⁻¹⁴ N.', 2, NULL, NULL),
('6120f871-2879-5be4-a8f5-9272f8b2987d', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 11, 11, 'What charge, in µC, would experience a force of 1.0 N in an electric field of 2.0 × 10⁵ N C⁻¹?', NULL, 1, 'numeric'::answer_type, '5 uC', 'µC', false, NULL, false, NULL, 'Q = F/E = 1.0 ÷ 2.0 × 10⁵ = 5.0 × 10⁻⁶ C. In µC: 5.0 × 10⁻⁶ × 10⁶ = 5.0. Mark scheme (2 marks). C1: Q = F/E. A1: Q = 5.0 µC.', 2, NULL, NULL),
('8263c4ee-3a05-5152-97e5-bc6264f9afd4', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 12, 12, 'A charged particle is moved from one point to another inside a uniform electric field. What happens to the electric force on it?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same in size and direction', NULL, false, NULL, false, NULL, 'A uniform field has the same E everywhere, so F = QE is constant. Mark scheme (1 mark). B1: D (It stays the same in size and direction).', 1, NULL, NULL),
('2fcabd98-7207-53a8-854e-45aa20b3109f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 13, 13, 'A singly charged ion (charge +e) experiences a force of 8.0 × 10⁻¹⁵ N. Calculate the electric field strength. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '50000', 'N C⁻¹', false, NULL, false, NULL, 'E = F/Q = 8.0 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁹ = 5.0 × 10⁴ N C⁻¹. Mark scheme (2 marks). C1: E = F/e. A1: E = 5.0 × 10⁴ N C⁻¹.', 2, NULL, NULL),
('339ea4a0-76b9-58a7-ae52-f71cf2a9b721', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 14, 14, 'A charged particle in a uniform field has its charge doubled while its mass stays the same. What happens to its acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'a = F/m = QE/m, so with E and m fixed the acceleration is proportional to Q. Mark scheme (1 mark). B1: B (It doubles).', 1, NULL, NULL),
('b6225e80-c5e2-5c5f-b434-38384666a0b8', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 15, 15, 'A polystyrene ball carrying 4.0 µC hangs between two plates and is pushed sideways by an electric force of 0.012 N. What is the electric field strength at the ball?', NULL, 1, 'numeric'::answer_type, '3000', 'N C⁻¹', false, NULL, false, NULL, 'E = F/Q = 0.012 ÷ 4.0 × 10⁻⁶ = 3000 N C⁻¹. Mark scheme (2 marks). C1: E = F/Q. A1: E = 3000 N C⁻¹.', 2, NULL, NULL),
('17814169-4589-506d-bd01-c84b7aaf56b0', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 16, 16, 'A charge moves at right angles to a uniform electric field. How much work does the electric force do on it during this movement?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'Work = force × displacement in the direction of the force; here the displacement is perpendicular to F. Mark scheme (1 mark). B1: C (None).', 1, NULL, NULL),
('199753d0-6cfa-55a5-a500-540c143cb969', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 17, 17, 'Calculate the force on an electron in an electric field of 2.0 × 10⁵ N C⁻¹, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.2', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = eE = 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = 3.20 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: F = eE. A1: F = 3.2 × 10⁻¹⁴ N.', 2, NULL, NULL),
('2b81af1b-6398-52b6-8dd4-becc9ede2dc5', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 18, 18, 'An electron is released from rest in a uniform electric field. How does it move?', NULL, 1, 'multiple_choice'::answer_type, 'In the opposite direction to the field, with increasing speed', NULL, false, NULL, false, NULL, 'The force on a negative charge is opposite to E and constant, so it accelerates uniformly. Mark scheme (1 mark). B1: A (In the opposite direction to the field, with increasing speed).', 1, NULL, NULL),
('12e51f08-fe8f-5ebf-85b6-7e565868f114', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 19, 19, 'A charged particle in a uniform field feels a force of 6.0 µN. The field strength is halved. What is the new force, in µN?', NULL, 1, 'numeric'::answer_type, '3 uN', 'µN', false, NULL, false, NULL, 'F = QE, so halving E halves F: 6.0 ÷ 2 = 3.0 µN. Mark scheme (1 mark). A1: F = 3.0 µN.', 1, NULL, NULL),
('bc0f9f49-009f-51b4-8d74-9de30aa30cc1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 20, 20, 'An electron, a proton and an α-particle are placed in the same uniform electric field. Which has the largest acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'The electron', NULL, false, NULL, false, NULL, 'a = QE/m: the electron''s tiny mass gives by far the largest charge-to-mass ratio. Mark scheme (1 mark). B1: D (The electron).', 1, NULL, NULL),
('48782126-c124-58f5-9992-e3c3d2e0d1c8', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 21, 21, 'A small particle experiences a force of 4.8 × 10⁻¹⁴ N in a field of 1.0 × 10⁵ N C⁻¹. How many electronic charges does it carry? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, 'Q = F/E = 4.8 × 10⁻¹⁴ ÷ 1.0 × 10⁵ = 4.8 × 10⁻¹⁹ C. Number = 4.8 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 3.0. Mark scheme (2 marks). C1: Q = F/E then ÷ e. A1: n = 3.0.', 2, NULL, NULL),
('1cd7215b-eb70-5b68-8cf6-7f98793b2791', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 22, 22, 'A negative charge in an electric field experiences an upward force. In which direction is the field?', NULL, 1, 'multiple_choice'::answer_type, 'Downwards', NULL, false, NULL, false, NULL, 'The force on a negative charge is opposite to the field. Mark scheme (1 mark). B1: B (Downwards).', 1, NULL, NULL),
('e115cce2-9165-5683-9ff6-7177e426a8f1', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 23, 23, 'An oil drop of mass 1.6 × 10⁻¹⁵ kg is held stationary in an upward electric field of 4.9 × 10⁴ N C⁻¹. Calculate the charge on the drop, in units of 10⁻¹⁹ C. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '3.203', '10⁻¹⁹ C', false, NULL, false, NULL, 'Electric force balances weight: QE = mg, so Q = 1.6 × 10⁻¹⁵ × 9.81 ÷ 4.9 × 10⁴ = 3.20 × 10⁻¹⁹ C. Mark scheme (3 marks). M1: QE = mg. C1: substitution. A1: Q = 3.20 × 10⁻¹⁹ C.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fge648c328-t fge648c328-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge648c328-t">Stationary oil drop</title><desc id="fge648c328-d">An oil drop of mass 1.6 × 10⁻¹⁵ kg held stationary in an upward electric field of 4.9 × 10⁴ N C⁻¹: the electric force balances its weight.</desc><rect x="70" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="58" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="58" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><circle cx="180" cy="110" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="101" x2="180" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,60 183.8,68.2 176.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electric force</text><line x1="180" y1="119" x2="180" y2="153.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,160 176.2,151.8 183.8,151.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="150" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text><text x="166" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.6 × 10⁻¹⁵ kg</text><text x="180" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 4.9 × 10⁴ N C⁻¹ (upward)</text></svg>', 'An oil drop of mass 1.6 × 10⁻¹⁵ kg held stationary in an upward electric field of 4.9 × 10⁴ N C⁻¹: the electric force balances its weight.'),
('4391568e-3ae8-56b1-b491-ce2d4ac62d35', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 24, 24, 'Calculate the acceleration of an electron in a uniform electric field of 3.0 × 10³ N C⁻¹. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '5.269e14', 'm s⁻²', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 3.0 × 10³ ÷ 9.11 × 10⁻³¹ = 5.27 × 10¹⁴ m s⁻². Mark scheme (3 marks). C1: F = eE. C1: a = F/m. A1: a = 5.27 × 10¹⁴ m s⁻².', 3, NULL, NULL),
('7cce1acd-f775-5553-8047-3a48b5c11e16', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 25, 25, 'A proton starts from rest in a uniform electric field of 1.0 × 10⁴ N C⁻¹ and travels 5.0 cm along the field. Calculate its final speed. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '3.095e5', 'm s⁻¹', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 1.67 × 10⁻²⁷ = 9.58 × 10¹¹ m s⁻². v² = 2as, so v = √(2 × 9.581 × 10¹¹ × 0.050) = 3.10 × 10⁵ m s⁻¹. Mark scheme (4 marks). C1: a = eE/m. M1: v² = u² + 2as with u = 0. C1: substitution. A1: v = 3.10 × 10⁵ m s⁻¹.', 4, NULL, NULL),
('4d13407f-d954-59e9-8ad3-9d1a1777f86c', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 26, 26, 'An electron is moving in the same direction as a uniform electric field. What happens to its speed?', NULL, 2, 'multiple_choice'::answer_type, 'It decreases, because the force on it is opposite to its motion', NULL, false, NULL, false, NULL, 'The force on an electron is opposite to E, so moving along E it decelerates. Mark scheme (3 marks). C1: force opposite to E for electron. C1: decelerates. A1: C (It decreases, because the force on it is opposite to its motion).', 3, NULL, NULL),
('18d23520-b7f4-5097-8572-d6ebb65d5962', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 27, 27, 'A proton is in a uniform electric field of 500 N C⁻¹ near the Earth''s surface. Calculate the ratio of the electric force on it to its weight. Take e = 1.60 × 10⁻¹⁹ C, mₚ = 1.67 × 10⁻²⁷ kg and g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '4.883e9', NULL, false, NULL, false, NULL, 'F = eE = 1.60 × 10⁻¹⁹ × 500 = 8.00 × 10⁻¹⁷ N. W = mg = 1.67 × 10⁻²⁷ × 9.81 = 1.64 × 10⁻²⁶ N. Ratio = 8.000 × 10⁻¹⁷ ÷ 1.638 × 10⁻²⁶ = 4.88 × 10⁹. Mark scheme (3 marks). C1: F = eE and W = mg. C1: ratio. A1: ratio = 4.88 × 10⁹.', 3, NULL, NULL),
('88d5b130-0fef-5818-b107-d2f60eaa18ce', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 28, 28, 'An electron moving at 5.0 × 10⁶ m s⁻¹ enters a region where there is a uniform field of 2.0 × 10³ N C⁻¹ in the same direction as its velocity. Calculate how far it travels before it stops, in cm. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '3.559 cm', 'cm', false, NULL, false, NULL, 'The force is opposite to its motion: deceleration a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10³ ÷ 9.11 × 10⁻³¹ = 3.51 × 10¹⁴ m s⁻². s = u²/2a = (5.0 × 10⁶)² ÷ (2 × 3.513 × 10¹⁴) = 0.0356 m. In cm: 0.03559 × 100 = 3.56. Mark scheme (4 marks). B1: force opposite to motion. C1: a = eE/m. C1: 0 = u² − 2as. A1: s = 3.56 cm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg3928490e-t fg3928490e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3928490e-t">Electron moving along a field</title><desc id="fg3928490e-d">Uniform field lines of 2.0 × 10³ N C⁻¹ pointing to the right; an electron moves to the right, in the same direction as the field, at 5.0 × 10⁶ m s⁻¹.</desc><line x1="20" y1="30" x2="315.1" y2="30" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,30 313.7,33 313.7,27" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="70" x2="315.1" y2="70" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,70 313.7,73 313.7,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="315.1" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,110 313.7,113 313.7,107" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="150" x2="315.1" y2="150" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,150 313.7,153 313.7,147" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="190" x2="315.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,190 313.7,193 313.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="318" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">E = 2.0 × 10³ N C⁻¹</text><circle cx="110" cy="150" r="9" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="110" cy="150" r="2.4" style="fill:currentColor;stroke:none"/><line x1="121" y1="150" x2="233.7" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="240,150 231.8,153.8 231.8,146.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="250" y="130" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">5.0 × 10⁶ m s⁻¹</text><text x="94" y="132" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">electron</text></svg>', 'Uniform field lines of 2.0 × 10³ N C⁻¹ pointing to the right; an electron moves to the right, in the same direction as the field, at 5.0 × 10⁶ m s⁻¹.'),
('4825cbc4-a120-5407-8d84-ff98e22ba268', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 29, 29, 'A charged particle is projected at right angles to a uniform electric field. Which quantity stays constant while it is in the field?', NULL, 2, 'multiple_choice'::answer_type, 'Its velocity component at right angles to the field', NULL, false, NULL, false, NULL, 'There is no force perpendicular to E, so that component is unchanged; the component along E changes uniformly. Mark scheme (3 marks). C1: force only along E. C1: perpendicular component unchanged. A1: A (Its velocity component at right angles to the field).', 3, NULL, NULL),
('a705a1e5-1378-5c84-8f3e-7bf317f42aaf', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 30, 30, 'In an ink-jet printer, an ink drop of mass 2.0 × 10⁻¹⁰ kg carries a charge of 4.0 × 10⁻¹³ C and passes between deflecting plates where the field is 8.0 × 10⁵ N C⁻¹. Calculate the acceleration of the drop due to the field.', NULL, 2, 'numeric'::answer_type, '1600', 'm s⁻²', false, NULL, false, NULL, 'a = QE/m = 4.0 × 10⁻¹³ × 8.0 × 10⁵ ÷ 2.0 × 10⁻¹⁰ = 1600 m s⁻². Mark scheme (3 marks). C1: F = QE. C1: a = F/m. A1: a = 1600 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg597f604c-t fg597f604c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg597f604c-t">Ink drop between deflecting plates</title><desc id="fg597f604c-d">A positively charged ink drop passes between deflecting plates where the field is 8.0 × 10⁵ N C⁻¹ (upwards), and is deflected along the field.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><line x1="110" y1="164" x2="110" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,56 113,62.3 107,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="164" x2="140" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,56 143,62.3 137,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="164" x2="170" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,56 173,62.3 167,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="164" x2="200" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,56 203,62.3 197,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="164" x2="230" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,56 233,62.3 227,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="164" x2="260" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,56 263,62.3 257,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="164" x2="290" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,56 293,62.3 287,62.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 8.0 × 10⁵ N C⁻¹</text><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">ink drop</text><polyline points="90,110 97.3,110 104.7,109.8 112,109.6 119.3,109.3 126.7,108.8 134,108.3 141.3,107.7 148.7,107 156,106.2 163.3,105.3 170.7,104.4 178,103.3 185.3,102.1 192.7,100.9 200,99.5 207.3,98.1 214.7,96.5 222,94.9 229.3,93.2 236.7,91.3 244,89.4 251.3,87.4 258.7,85.3 266,83.1 273.3,80.8 280.7,78.5 288,76 295.3,73.4 302.7,70.8 310,68" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/></svg>', 'A positively charged ink drop passes between deflecting plates where the field is 8.0 × 10⁵ N C⁻¹ (upwards), and is deflected along the field.'),
('86d35183-94c0-5c43-a4ac-5210b7e0ef1e', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 31, 31, 'A singly charged lithium ion (mass 1.15 × 10⁻²⁶ kg) is in a uniform field of 4.0 × 10⁴ N C⁻¹. Calculate its acceleration. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.565e11', 'm s⁻²', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 4.0 × 10⁴ ÷ 1.15 × 10⁻²⁶ = 5.57 × 10¹¹ m s⁻². Mark scheme (3 marks). C1: F = eE. C1: a = F/m. A1: a = 5.57 × 10¹¹ m s⁻².', 3, NULL, NULL),
('bc2504ae-19a5-5c1d-8644-ac92a540f6e7', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 32, 32, 'An oil drop carrying a negative charge is held stationary between two horizontal plates. It suddenly picks up one more electron. What happens next, with the p.d. unchanged?', NULL, 2, 'multiple_choice'::answer_type, 'It accelerates upwards, because the upward electric force is now larger than its weight', NULL, false, NULL, false, NULL, 'The charge magnitude increases, so QE exceeds mg; the electron''s extra mass is negligible. Mark scheme (4 marks). C1: QE increases. C1: extra mass negligible. C1: net upward force. A1: D (It accelerates upwards, because the upward electric force is now larger than its weight).', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fga0448a25-t fga0448a25-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga0448a25-t">Stationary oil drop</title><desc id="fga0448a25-d">A negatively charged oil drop held stationary between two horizontal plates: the upward electric force balances its weight.</desc><rect x="70" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="58" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="58" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><circle cx="180" cy="110" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="101" x2="180" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,60 183.8,68.2 176.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electric force</text><line x1="180" y1="119" x2="180" y2="153.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,160 176.2,151.8 183.8,151.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="150" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text></svg>', 'A negatively charged oil drop held stationary between two horizontal plates: the upward electric force balances its weight.'),
('e5847e55-a1bf-5620-8fe2-90732fa64897', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 33, 33, 'An electron moves 3.0 cm in the direction opposite to a uniform field of 2.0 × 10⁴ N C⁻¹. Calculate the work done on it by the electric force, in units of 10⁻¹⁷ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '9.6', '10⁻¹⁷ J', false, NULL, false, NULL, 'The force on the electron is opposite to E, in its direction of motion, so the work is positive: W = eEd = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ × 0.030 = 9.60 × 10⁻¹⁷ J. Mark scheme (3 marks). C1: F = eE. C1: W = Fd. A1: W = 9.60 × 10⁻¹⁷ J.', 3, NULL, NULL),
('e7c1c9bd-0b57-5bcb-9acd-ede6e6c78a9a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 34, 34, 'A proton starts from rest in a field of 2.0 × 10³ N C⁻¹. Calculate the time it takes to reach a speed of 1.0 × 10⁵ m s⁻¹, in µs. Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '0.5219 us', 'µs', false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10³ ÷ 1.67 × 10⁻²⁷ = 1.92 × 10¹¹ m s⁻². t = v/a = 1.0 × 10⁵ ÷ 1.916 × 10¹¹ = 5.22 × 10⁻⁷ s. In µs: 5.219 × 10⁻⁷ × 10⁶ = 0.522. Mark scheme (3 marks). C1: a = eE/m. C1: t = v/a. A1: t = 0.522 µs.', 3, NULL, NULL),
('3e26fdc0-4cfd-555d-a4fc-f9f1a860ba0f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 35, 35, 'An electron and a proton are in the same uniform field. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Forces equal in size; the electron''s acceleration is about 1840 times larger', NULL, false, NULL, false, NULL, 'F = eE for both; a = F/m, and mₚ/mₑ ≈ 1840. Mark scheme (3 marks). C1: equal forces. C1: a ∝ 1/m. A1: B (Forces equal in size; the electron''s acceleration is about 1840 times larger).', 3, NULL, NULL),
('b1971e2a-484a-5b47-a722-295869ee0511', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 36, 36, 'A small sphere of mass 2.0 × 10⁻⁴ kg carrying a charge of 15 nC hangs on a thread between two vertical parallel plates 6.0 cm apart with a p.d. of 3.0 kV. Calculate the angle the thread makes with the vertical. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '20.92', '°', false, NULL, false, NULL, 'E = 3.0 × 10³ ÷ 0.060 = 5.0 × 10⁴ V m⁻¹. F = QE = 15 × 10⁻⁹ × 5.0 × 10⁴ = 7.5 × 10⁻⁴ N. tan θ = F/mg = 7.5 × 10⁻⁴ ÷ (2.0 × 10⁻⁴ × 9.81) = 0.3823, so θ = tan⁻¹ 0.3823 = 20.9°. Mark scheme (4 marks). C1: E = V/d. C1: F = QE. M1: tan θ = F/mg. A1: θ = 20.9°.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 270" role="img" aria-labelledby="fg507832e7-t fg507832e7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg507832e7-t">Sphere between vertical plates</title><desc id="fg507832e7-d">A sphere of mass 2.0 × 10⁻⁴ kg carrying 15 nC hangs on a thread between vertical plates 6.0 cm apart with a p.d. of 3.0 kV; the horizontal field deflects the thread.</desc><line x1="70" y1="30" x2="170" y2="30" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="30" x2="67" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="30" x2="85" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="111" y1="30" x2="103" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="129" y1="30" x2="121" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="30" x2="139" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165" y1="30" x2="157" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="30" x2="120" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 4"/><line x1="120" y1="30" x2="161.3" y2="174.2" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="161.3" cy="174.2" r="12" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="158" y1="162.7" x2="143.2" y2="111" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="141.5,105 147.4,111.8 140.1,113.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="163.2" y="132" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">T</text><line x1="161.3" y1="186.2" x2="161.3" y2="237.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="161.3,244.2 157.5,236 165.1,236" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="171.3" y="240.2" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">W</text><line x1="173.3" y1="174.2" x2="225" y2="174.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="231.3,174.2 223.2,178 223.2,170.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="237.3" y="174.2" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">F</text><line x1="20" y1="252" x2="84.4" y2="252" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="90,252 82.7,255.4 82.7,248.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="98" y="252" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E (plates 6.0 cm apart, 3.0 kV)</text></svg>', 'A sphere of mass 2.0 × 10⁻⁴ kg carrying 15 nC hangs on a thread between vertical plates 6.0 cm apart with a p.d. of 3.0 kV; the horizontal field deflects the thread.'),
('584d080c-5f49-5e16-9ff4-87f150586873', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 37, 37, 'A dust particle of mass 5.0 × 10⁻¹³ kg carries a charge of 8.0 × 10⁻¹⁵ C. Calculate the vertical electric field strength needed to stop it falling. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '613.1', 'N C⁻¹', false, NULL, false, NULL, 'QE = mg, so E = 5.0 × 10⁻¹³ × 9.81 ÷ 8.0 × 10⁻¹⁵ = 613 N C⁻¹. Mark scheme (3 marks). M1: QE = mg. C1: substitution. A1: E = 613 N C⁻¹.', 3, NULL, NULL),
('dc14c795-945e-5ac9-9b49-3a9d62612b5f', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 38, 38, 'A positive ion and an electron are released together from the midpoint between two charged parallel plates. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'They move in opposite directions, and the electron reaches its plate first', NULL, false, NULL, false, NULL, 'Equal and opposite forces; the electron''s far larger acceleration means a shorter time to cover the same distance. Mark scheme (3 marks). C1: opposite forces. C1: larger a for electron. A1: C (They move in opposite directions, and the electron reaches its plate first).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg31bfad57-t fg31bfad57-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg31bfad57-t">Ion and electron between plates</title><desc id="fg31bfad57-d">A positive ion and an electron released together from rest at the midpoint between two charged parallel plates (top positive).</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><circle cx="182.4" cy="110" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="182.4" y="110.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">+</text><text x="194.4" y="98" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">ion</text><circle cx="217.6" cy="110" r="8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="217.6" y="110.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309);font-weight:700">−</text><text x="229.6" y="98" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electron</text></svg>', 'A positive ion and an electron released together from rest at the midpoint between two charged parallel plates (top positive).'),
('76448f4a-66da-52c5-951b-2d034081cf1a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 39, 39, 'An oil drop of radius 1.2 µm and density 900 kg m⁻³ is held stationary between two horizontal plates 8.0 mm apart when the p.d. between them is 1065 V. (a) Calculate the mass of the drop. (b) Calculate the charge on the drop, in units of 10⁻¹⁹ C. (c) State the number of excess electrons on the drop. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '4.8', '10⁻¹⁹ C', false, NULL, false, NULL, '(a) m = ρ × (4/3)πr³ = 900 × 4/3 × π × (1.2 × 10⁻⁶)³ = 6.51 × 10⁻¹⁵ kg. (b) QV/d = mg, so Q = mgd/V = 6.514 × 10⁻¹⁵ × 9.81 × 8.0 × 10⁻³ ÷ 1065 = 4.80 × 10⁻¹⁹ C. (c) 4.800 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 3.00, so 3 electrons. Mark scheme (6 marks). C1: m = ρ(4/3)πr³. M1: QE = mg with E = V/d. C1: substitution. C1: Q value. B1: 3 electrons. A1: Q = 4.80 × 10⁻¹⁹ C.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fg9a7b37f1-t fg9a7b37f1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9a7b37f1-t">Stationary oil drop</title><desc id="fg9a7b37f1-d">An oil drop of radius 1.2 µm held stationary between horizontal plates 8.0 mm apart with a p.d. of 1065 V.</desc><rect x="70" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="58" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="58" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><circle cx="180" cy="110" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="101" x2="180" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,60 183.8,68.2 176.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electric force</text><line x1="180" y1="119" x2="180" y2="153.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,160 176.2,151.8 183.8,151.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="150" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text><text x="166" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">radius 1.2 µm</text><polygon points="312,50 315,56.3 309,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="312" y1="54.9" x2="312" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="312,170 309,163.7 315,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="110" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">8.0 mm</text><text x="180" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">p.d. 1065 V</text></svg>', 'An oil drop of radius 1.2 µm held stationary between horizontal plates 8.0 mm apart with a p.d. of 1065 V.'),
('72db8174-a2a8-5188-80ec-ca090a17b532', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 40, 40, 'An electron moving at 3.0 × 10⁷ m s⁻¹ enters a uniform field of 2.0 × 10⁴ N C⁻¹ at right angles to the field. The field region is 6.0 cm long. (a) Calculate the time the electron spends in the field. (b) Calculate the velocity component it gains along the field direction. (c) Calculate the angle between its velocity and its original direction as it leaves the field. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '13.18', '°', false, NULL, false, NULL, '(a) t = 0.060 ÷ 3.0 × 10⁷ = 2.0 × 10⁻⁹ s. (b) a = eE/m = 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ ÷ 9.11 × 10⁻³¹ = 3.51 × 10¹⁵ m s⁻²; v_y = at = 3.513 × 10¹⁵ × 2.0 × 10⁻⁹ = 7.03 × 10⁶ m s⁻¹. (c) tan θ = 7.025 × 10⁶ ÷ 3.0 × 10⁷ = 0.2342, so θ = tan⁻¹ 0.2342 = 13.2°. Mark scheme (6 marks). C1: t = L/v. C1: a = eE/m. C1: v_y = at. M1: tan θ = v_y/v_x. C1: angle. A1: θ = 13.2°.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fgedba0df6-t fgedba0df6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgedba0df6-t">Electron crossing a field</title><desc id="fgedba0df6-d">An electron moving at 3.0 × 10⁷ m s⁻¹ enters a uniform field of 2.0 × 10⁴ N C⁻¹ at right angles; the field region is 6.0 cm long.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polygon points="90,196 96.3,193 96.3,199" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="196" x2="305.1" y2="196" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="310,196 303.7,199 303.7,193" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="200" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 cm</text><text x="200" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 2.0 × 10⁴ N C⁻¹</text><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">3.0 × 10⁷ m s⁻¹</text><polyline points="90,110 97.3,110 104.7,109.8 112,109.6 119.3,109.3 126.7,108.8 134,108.3 141.3,107.7 148.7,107 156,106.2 163.3,105.3 170.7,104.4 178,103.3 185.3,102.1 192.7,100.9 200,99.5 207.3,98.1 214.7,96.5 222,94.9 229.3,93.2 236.7,91.3 244,89.4 251.3,87.4 258.7,85.3 266,83.1 273.3,80.8 280.7,78.5 288,76 295.3,73.4 302.7,70.8 310,68" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/></svg>', 'An electron moving at 3.0 × 10⁷ m s⁻¹ enters a uniform field of 2.0 × 10⁴ N C⁻¹ at right angles; the field region is 6.0 cm long.'),
('063728be-90fb-5836-84c2-dd54f9b25558', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 41, 41, 'A proton and an electron enter the same uniform electric field with the same speed, moving at right angles to the field, and travel the same distance through it. (a) Explain why both spend the same time in the field. (b) Compare the forces on them. (c) Calculate the ratio (sideways deflection of proton) ÷ (sideways deflection of electron). Give only the answer to (c). Take mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '5.455e-4', NULL, false, NULL, false, NULL, '(a) Their velocity components perpendicular to the field are equal and unchanged, so t = L/v is the same. (b) Equal in magnitude, eE, but in opposite directions. (c) y = ½at² with a = eE/m, so y ∝ 1/m: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = 5.46 × 10⁻⁴, and the deflections are in opposite directions. Mark scheme (5 marks). B1: same time, constant perpendicular velocity. B1: equal and opposite forces. M1: y ∝ a ∝ 1/m. C1: mass ratio. A1: ratio = 5.46 × 10⁻⁴.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fgc599319a-t fgc599319a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc599319a-t">Proton and electron in a field</title><desc id="fgc599319a-d">A proton and an electron enter the same uniform field between parallel plates with the same speed, moving at right angles to the field.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">proton and electron</text></svg>', 'A proton and an electron enter the same uniform field between parallel plates with the same speed, moving at right angles to the field.'),
('db6869b0-0806-5fe7-89c7-c0a2254bc10a', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 42, 42, 'An oil drop of mass 4.0 × 10⁻¹⁵ kg carrying a charge of 6.4 × 10⁻¹⁹ C is between horizontal plates where there is an upward field of 8.0 × 10⁴ N C⁻¹. (a) Calculate the electric force on the drop. (b) Calculate its weight. (c) Ignoring air resistance, calculate the drop''s acceleration. (d) Explain why, in practice, the drop soon moves at a constant speed. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '2.99', 'm s⁻²', false, NULL, false, NULL, '(a) F = QE = 6.4 × 10⁻¹⁹ × 8.0 × 10⁴ = 5.12 × 10⁻¹⁴ N upwards. (b) W = 4.0 × 10⁻¹⁵ × 9.81 = 3.92 × 10⁻¹⁴ N. (c) a = (F − W)/m = (5.120 × 10⁻¹⁴ − 3.924 × 10⁻¹⁴) ÷ 4.0 × 10⁻¹⁵ = 2.99 m s⁻², upwards. (d) Air resistance increases with speed until it balances the resultant force, so the drop reaches a terminal velocity. Mark scheme (6 marks). C1: F = QE. C1: W = mg. M1: resultant force = F − W. C1: a = F_net/m. B1: drag rises to give terminal velocity. A1: a = 2.99 m s⁻².', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fgf6b139ee-t fgf6b139ee-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf6b139ee-t">Oil drop in an upward field</title><desc id="fgf6b139ee-d">An oil drop of mass 4.0 × 10⁻¹⁵ kg carrying 6.4 × 10⁻¹⁹ C between horizontal plates with an upward field of 8.0 × 10⁴ N C⁻¹.</desc><rect x="70" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="58" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="58" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><circle cx="180" cy="110" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="101" x2="180" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,60 183.8,68.2 176.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electric force</text><line x1="180" y1="119" x2="180" y2="153.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,160 176.2,151.8 183.8,151.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="150" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text><text x="166" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 × 10⁻¹⁵ kg</text><text x="180" y="24" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">E = 8.0 × 10⁴ N C⁻¹ (upward)</text></svg>', 'An oil drop of mass 4.0 × 10⁻¹⁵ kg carrying 6.4 × 10⁻¹⁹ C between horizontal plates with an upward field of 8.0 × 10⁴ N C⁻¹.'),
('9c156226-719b-5e7d-8265-9bb934612a11', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 43, 43, 'A proton moving at 2.0 × 10⁵ m s⁻¹ enters a region where a uniform field of 1.5 × 10³ N C⁻¹ points opposite to its velocity. (a) Calculate its deceleration. (b) Calculate the time taken for it to stop. (c) Calculate the distance it travels before stopping. (d) Describe its motion after it stops. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '0.1392', 'm', false, NULL, false, NULL, '(a) a = eE/m = 1.60 × 10⁻¹⁹ × 1.5 × 10³ ÷ 1.67 × 10⁻²⁷ = 1.44 × 10¹¹ m s⁻². (b) t = u/a = 2.0 × 10⁵ ÷ 1.437 × 10¹¹ = 1.39 × 10⁻⁶ s. (c) s = u²/2a = (2.0 × 10⁵)² ÷ (2 × 1.437 × 10¹¹) = 0.139 m. (d) The force still acts along the field, so it accelerates back the way it came and leaves the region with its original speed. Mark scheme (5 marks). C1: a = eE/m. C1: t = u/a. M1: s = u²/2a. B1: returns with same speed. A1: s = 0.139 m.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg4ea6d047-t fg4ea6d047-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4ea6d047-t">Proton moving against a field</title><desc id="fg4ea6d047-d">Uniform field lines of 1.5 × 10³ N C⁻¹ pointing to the right; a proton moves to the left, against the field, at 2.0 × 10⁵ m s⁻¹.</desc><line x1="20" y1="30" x2="315.1" y2="30" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,30 313.7,33 313.7,27" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="70" x2="315.1" y2="70" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,70 313.7,73 313.7,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="315.1" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,110 313.7,113 313.7,107" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="150" x2="315.1" y2="150" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,150 313.7,153 313.7,147" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="190" x2="315.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,190 313.7,193 313.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="318" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">E = 1.5 × 10³ N C⁻¹</text><circle cx="230" cy="150" r="9" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="230" cy="150" r="2.4" style="fill:currentColor;stroke:none"/><line x1="219" y1="150" x2="106.3" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="100,150 108.2,146.2 108.2,153.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="90" y="130" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 × 10⁵ m s⁻¹</text><text x="214" y="132" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">proton</text></svg>', 'Uniform field lines of 1.5 × 10³ N C⁻¹ pointing to the right; a proton moves to the left, against the field, at 2.0 × 10⁵ m s⁻¹.'),
('934df9d2-d637-5d0e-b312-c45e1bd34166', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 44, 44, 'A ball of mass 0.010 kg carrying +2.0 µC is released from rest in a uniform horizontal electric field of 5.0 × 10⁴ N C⁻¹. (a) Calculate the horizontal electric force on the ball. (b) Calculate the resultant force on the ball. (c) Calculate the angle between the ball''s path and the vertical, and explain why the path is a straight line. Give only the angle from (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '45.55', '°', false, NULL, false, NULL, '(a) F = QE = 2.0 × 10⁻⁶ × 5.0 × 10⁴ = 0.10 N. (b) Weight = 0.010 × 9.81 = 0.0981 N; resultant = √(0.10² + 0.0981²) = 0.140 N. (c) tan θ = 0.10 ÷ 0.0981 = 1.019, so θ = tan⁻¹ 1.019 = 45.5°. Starting from rest with a constant resultant force, the ball accelerates along the line of that force. Mark scheme (6 marks). C1: F = QE. C1: weight. C1: resultant by Pythagoras. M1: tan θ = F_E/W. B1: constant force from rest gives straight line. A1: θ = 45.5°.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 220" role="img" aria-labelledby="fgaa2fd3c6-t fgaa2fd3c6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaa2fd3c6-t">Forces on the ball</title><desc id="fgaa2fd3c6-d">Forces on a ball of mass 0.010 kg carrying +2.0 µC in a uniform horizontal field of 5.0 × 10⁴ N C⁻¹: its weight acts vertically down and the electric force acts horizontally.</desc><line x1="120" y1="70" x2="213.7" y2="70" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="220,70 211.8,73.8 211.8,66.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="234" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electric force</text><line x1="120" y1="70" x2="120" y2="161.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="120,168 116.2,159.8 123.8,159.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="120" y="182" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text><circle cx="120" cy="70" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Forces on a ball of mass 0.010 kg carrying +2.0 µC in a uniform horizontal field of 5.0 × 10⁴ N C⁻¹: its weight acts vertically down and the electric force acts horizontally.'),
('bc25684b-d92f-5341-82bb-12099aa813a6', 'a6c1f6cd-641d-4d35-8950-b05e6c80ecf5', 'd1772ef2-4c08-4e93-86a4-2802dcbf78cc', 'a-level', '21.4', '9702 coursebook 21.4 · Force on a charge', 45, 45, 'A mineral separator lets a mixture of charged particles fall from rest between two vertical plates that produce a horizontal field of 5.0 × 10⁵ N C⁻¹. One type of particle has a charge-to-mass ratio of 2.0 × 10⁻⁶ C kg⁻¹. The particles fall 1.0 m before leaving the plates. (a) Calculate the horizontal acceleration of this type of particle. (b) Calculate the time taken to fall 1.0 m. (c) Calculate its horizontal displacement when it leaves the plates, in cm. (d) Explain how this separates particles with charges of opposite sign. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '10.19 cm', 'cm', false, NULL, false, NULL, '(a) a = (Q/m)E = 2.0 × 10⁻⁶ × 5.0 × 10⁵ = 1.0 m s⁻². (b) t = √(2 × 1.0 ÷ 9.81) = 0.452 s. (c) x = ½at² = 0.5 × 1.0 × 0.4515² = 0.102 m. In cm: 0.1019 × 100 = 10.2. (d) Positive particles are pushed one way along the field and negative ones the other, so they land in different collecting bins. Mark scheme (6 marks). C1: a = (Q/m)E. C1: vertical motion: t from s = ½gt². M1: horizontal and vertical motions independent. C1: x = ½at². B1: opposite charges deflected opposite ways. A1: x = 10.2 cm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg472e0b28-t fg472e0b28-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg472e0b28-t">Path in the separator</title><desc id="fg472e0b28-d">Path of one type of particle falling from rest between vertical plates with a horizontal field of 5.0 × 10⁵ N C⁻¹ and charge-to-mass ratio 2.0 × 10⁻⁶ C kg⁻¹: a straight line slanting sideways as it falls 1.0 m.</desc><line x1="39.8" y1="34" x2="39.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="153.8" y1="34" x2="153.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="267.9" y1="34" x2="267.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="223.1" x2="382" y2="223.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="128.5" x2="382" y2="128.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="34" x2="388" y2="34" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="242" x2="39.8" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,34 385.7,37 385.7,31" style="fill:currentColor;stroke:none"/><polygon points="39.8,24 42.7,30.3 36.8,30.3" style="fill:currentColor;stroke:none"/><line x1="39.8" y1="34" x2="39.8" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="153.8" y1="34" x2="153.8" y2="38" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="153.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.04</text><line x1="267.9" y1="34" x2="267.9" y2=